# Chapter 18 Oscillations — part b: 18.6 to 18.10.

def Tspring(m, k):
    return 2 * pi * sqrt(m / k)


def Tpend(L, gg=9.81):
    return 2 * pi * sqrt(L / gg)


# ═════════════════════════ 18.6 Frequency and angular frequency (need 15/18/11) ═════════════════════════
lesson('18.6')
N('E', 1, 'A wind-turbine tower sways back and forth at 0.80 Hz. Calculate the angular frequency of the sway.', 2 * pi * 0.80, 'rad s⁻¹', f'ω = 2πf = 2π × 0.80 = {sf(1.6 * pi)} rad s⁻¹', [], aq='ω')
N('E', 1, 'Mains electricity in Europe alternates at 50 Hz. Calculate its angular frequency.', 100 * pi, 'rad s⁻¹', f'ω = 2πf = 2π × 50 = {sf(100 * pi)} rad s⁻¹', [], aq='ω')
N('E', 2, 'An oscillator has angular frequency 31.4 rad s⁻¹. Calculate its frequency and period. Give the period.', 2 * pi / 31.4, 's', f'f = ω/2π = 31.4 ÷ 2π = {sf(31.4 / (2 * pi))} Hz. T = 1/f = 2π ÷ 31.4 = {sf(2 * pi / 31.4)} s', ['C1: f = ω/2π or T = 2π/ω'], aq='T')
M('E', 1, 'Which expression gives the angular frequency ω of an oscillation of period T?', '2π/T', ['T/2π', '2πT', '1/T'], 'ω = 2πf and f = 1/T, so ω = 2π/T.')
M('E', 1, 'What is the unit of angular frequency?', 'rad s⁻¹', ['Hz s', 'rad', 's'], 'Angular frequency is the rate of change of phase angle: radians per second.')
N('E', 2, 'A heartbeat has a period of 0.75 s. Calculate its angular frequency.', 2 * pi / 0.75, 'rad s⁻¹', f'ω = 2π/T = 2π ÷ 0.75 = {sf(2 * pi / 0.75)} rad s⁻¹', ['C1: ω = 2π/T'], aq='ω')
N('E', 2, 'Calculate the frequency of an oscillation with angular frequency 2.0 × 10³ rad s⁻¹.', 2.0e3 / (2 * pi), 'Hz', f'f = ω/2π = 2.0 × 10³ ÷ 2π = {sf(2e3 / (2 * pi))} Hz', ['C1: f = ω/2π'], aq='f')
M('E', 1, 'Two oscillators have frequencies f and 3f. What is the ratio of their angular frequencies (second/first)?', '3', ['1/3', '9', '6π'], 'ω = 2πf ∝ f, so the ratio is 3.')
N('E', 2, 'A mass on a spring has ω = 15 rad s⁻¹. How many oscillations does it make in 10 s?', 15 * 10 / (2 * pi), None, f'f = ω/2π = 15 ÷ 2π = {sf(15 / (2 * pi))} Hz, so N = ft = {sf(15 / (2 * pi), 4)} × 10 = {sf(150 / (2 * pi))}', ['C1: f = ω/2π, N = ft'], aq='N', tol=0.02)
N('E', 2, 'A quartz crystal in a watch vibrates at 32 768 Hz. Calculate its angular frequency.', 2 * pi * 32768, 'rad s⁻¹', f'ω = 2πf = 2π × 32768 = {sf(2 * pi * 32768)} rad s⁻¹', ['C1: ω = 2πf'], aq='ω')
M('E', 1, 'An oscillation has angular frequency 4π rad s⁻¹. What is its period?', '0.50 s', ['2.0 s', '4.0 s', '0.25 s'], 'T = 2π/ω = 2π/4π = 0.50 s.')
N('E', 2, 'A pendulum of length 0.50 m swings with small oscillations. Calculate its angular frequency.' + take('g'), sqrt(9.81 / 0.50), 'rad s⁻¹', f'ω = √(g/L) = √(9.81 ÷ 0.50) = {sf(sqrt(19.62))} rad s⁻¹', ['C1: ω = √(g/L)'], aq='ω')
N('E', 2, 'A 0.80 kg mass on a spring of constant 320 N m⁻¹ oscillates. Calculate ω.', sqrt(320 / 0.80), 'rad s⁻¹', 'ω = √(k/m) = √(320 ÷ 0.80) = 20 rad s⁻¹', ['C1: ω = √(k/m)'], sig=2, aq='ω')
M('E', 1, 'Why is angular frequency used in s.h.m. equations instead of frequency?', 'It makes the equations neater: x = x₀ sin ωt instead of x = x₀ sin 2πft', ['Angular frequency is always larger than frequency', 'Frequency has no unit', 'Only circular motion has a frequency'], 'ω = 2πf absorbs the 2π, so the phase angle ωt is in radians directly.')
N('E', 2, 'A vibrating molecule bond has ω = 1.6 × 10¹⁴ rad s⁻¹. Calculate its frequency.', 1.6e14 / (2 * pi), 'Hz', f'f = ω/2π = 1.6 × 10¹⁴ ÷ 2π = {sf(1.6e14 / (2 * pi))} Hz', ['C1: f = ω/2π'], aq='f')
# medium
N('M', 3, 'A child on a swing makes 12 complete swings in 30 s. Calculate the angular frequency and the length of the swing (treat it as a simple pendulum). Give the length.' + take('g'), 9.81 / (2 * pi * 12 / 30) ** 2, 'm',
  f'f = 12 ÷ 30 = 0.40 Hz, ω = 2πf = {sf(0.8 * pi)} rad s⁻¹. ω² = g/L, so L = g/ω² = 9.81 ÷ ({sf(0.8 * pi)})² = {sf(9.81 / (0.8 * pi) ** 2)} m', ['C1: f = N/t', 'C1: ω = 2πf', 'C1: L = g/ω²'], aq='L')
N('M', 3, 'A spring of constant 45 N m⁻¹ has a mass hung on it, giving ω = 7.5 rad s⁻¹. Calculate the mass.', 45 / 7.5 ** 2, 'kg', f'ω² = k/m, so m = k/ω² = 45 ÷ 7.5² = {sf(45 / 56.25)} kg', ['C1: ω² = k/m', 'C1: rearranged'], aq='m')
M('M', 3, 'The mass on a spring is increased by a factor of 4. What happens to the angular frequency?', 'It halves', ['It doubles', 'It quarters', 'It is unchanged'], 'ω = √(k/m) ∝ 1/√m: √4 = 2, so ω halves.', ['C1: ω ∝ 1/√m', 'C1: factor of 2'])
N('M', 4, 'A mass of 0.30 kg on a spring oscillates with frequency 2.2 Hz. A second mass is added and the frequency falls to 1.6 Hz. Calculate the added mass.', 0.30 * (2.2 / 1.6) ** 2 - 0.30, 'kg',
  f'f ∝ 1/√m, so m₂ = m₁(f₁/f₂)² = 0.30 × (2.2 ÷ 1.6)² = {sf(0.3 * (2.2 / 1.6) ** 2)} kg. Added mass = {sf(0.3 * (2.2 / 1.6) ** 2, 4)} − 0.30 = {sf(0.3 * (2.2 / 1.6) ** 2 - 0.3)} kg', ['C1: f ∝ 1/√m', 'C1: m₂', 'C1: subtract'], aq='Δm')
N('M', 3, 'An oscillation has angular frequency 12 rad s⁻¹. Calculate the time taken for the phase to increase by π/3 rad.', (pi / 3) / 12, 's', f't = Δφ/ω = (π/3) ÷ 12 = {sf(pi / 36)} s', ['C1: phase = ωt', 'C1: t = Δφ/ω'], aq='t')
M('M', 3, 'Two pendulums have angular frequencies 2.0 rad s⁻¹ and 2.5 rad s⁻¹ in the same place. What is the ratio of their lengths (first/second)?', '1.56', ['0.64', '1.25', '0.80'], 'ω² = g/L, so L ∝ 1/ω²: L₁/L₂ = (2.5/2.0)² = 1.5625.', ['C1: L ∝ 1/ω²', 'C1: ratio'])
N('M', 3, 'A guitar string vibrates at angular frequency 1380 rad s⁻¹. Calculate the number of vibrations in 0.050 s.', 1380 * 0.050 / (2 * pi), None, f'f = 1380 ÷ 2π = {sf(1380 / (2 * pi))} Hz. N = ft = {sf(1380 / (2 * pi), 4)} × 0.050 = {sf(69 / (2 * pi))}', ['C1: f = ω/2π', 'C1: N = ft'], aq='N', tol=0.02)
N('M', 4, 'A pendulum on Mars has length 0.60 m and angular frequency 2.48 rad s⁻¹. Calculate g on Mars, and the period of a 1.0 m pendulum there. Give the period.', 2 * pi * sqrt(1.0 / (2.48 ** 2 * 0.60)), 's',
  f'g = ω²L = 2.48² × 0.60 = {sf(2.48 ** 2 * 0.6)} N kg⁻¹. For L = 1.0 m: T = 2π√(L/g) = 2π × √(1.0 ÷ {sf(2.48 ** 2 * 0.6, 4)}) = {sf(2 * pi * sqrt(1 / (2.48 ** 2 * 0.6)))} s', ['C1: g = ω²L', 'C1: T = 2π√(L/g)', 'C1: substitution'], aq='T')
M('M', 3, 'A student writes ω = 2π/f. Why is this wrong?', 'ω = 2πf; 2π/f has the wrong unit (rad s, not rad s⁻¹)', ['It is correct', 'ω = f/2π', 'ω = 2πT'], 'Angular frequency is 2π radians per period: ω = 2π/T = 2πf.', ['C1: ω = 2πf', 'C1: unit check'])
N('M', 3, 'An oscillator has period 0.25 s. Calculate its angular frequency and the angle (in degrees) its phase advances in 0.10 s. Give the angle.', degrees(2 * pi / 0.25 * 0.10), '°', f'ω = 2π ÷ 0.25 = {sf(8 * pi)} rad s⁻¹. Phase = ωt = {sf(8 * pi)} × 0.10 = {sf(0.8 * pi)} rad. In degrees: {sf(0.8 * pi, 4)} × 180 ÷ π = {sf(144)}°', ['C1: ω = 2π/T', 'C1: φ = ωt', 'C1: to degrees'], aq='φ')
N('M', 4, 'A diatomic molecule is modelled as two equal atoms on a spring; the effective (reduced) mass is 1.15 × 10⁻²⁶ kg and the bond constant is 1900 N m⁻¹. Calculate the angular frequency and frequency of the vibration. Give the frequency.', sqrt(1900 / 1.15e-26) / (2 * pi), 'Hz', f'ω = √(k/μ) = √(1900 ÷ 1.15 × 10⁻²⁶) = {sf(sqrt(1900 / 1.15e-26))} rad s⁻¹. f = ω/2π = {sf(sqrt(1900 / 1.15e-26), 4)} ÷ 2π = {sf(sqrt(1900 / 1.15e-26) / (2 * pi))} Hz', ['C1: ω = √(k/m)', 'C1: substitution', 'C1: f = ω/2π'], aq='f')
M('M', 3, 'A spring–mass system has ω = 10 rad s⁻¹ on Earth. On the Moon, what is ω?', '10 rad s⁻¹', ['4.1 rad s⁻¹', '24 rad s⁻¹', '1.6 rad s⁻¹'], 'ω = √(k/m) does not depend on g, so it is unchanged.', ['C1: ω = √(k/m)', 'C1: no g'])
N('M', 3, 'A pendulum has angular frequency 3.13 rad s⁻¹. Calculate its length.' + take('g'), 9.81 / 3.13 ** 2, 'm', f'L = g/ω² = 9.81 ÷ 3.13² = {sf(9.81 / 3.13 ** 2)} m', ['C1: ω² = g/L', 'C1: rearranged'], aq='L')
N('M', 3, 'A car on its suspension bounces at 1.2 Hz when empty (mass 1000 kg). Calculate ω and the suspension spring constant. Give the spring constant.', (2 * pi * 1.2) ** 2 * 1000, 'N m⁻¹', f'ω = 2π × 1.2 = {sf(2.4 * pi)} rad s⁻¹. k = mω² = 1000 × ({sf(2.4 * pi)})² = {sf(1000 * (2.4 * pi) ** 2)} N m⁻¹', ['C1: ω = 2πf', 'C1: k = mω²'], aq='k')
M('M', 4, 'Spring A (constant k) and spring B (constant 4k) each carry the same mass. Which statement is correct?', 'B oscillates with twice the angular frequency of A', ['B oscillates with four times the angular frequency of A', 'A oscillates with twice the angular frequency of B', 'Both have the same angular frequency'], 'ω = √(k/m) ∝ √k: √4 = 2.', ['C1: ω ∝ √k', 'C1: factor 2', 'C1: B faster'])
N('M', 3, 'A tuning fork has frequency 440 Hz. Calculate how long it takes for its phase to change by 3π rad.', 3 * pi / (2 * pi * 440), 's', f't = Δφ/ω = 3π ÷ (2π × 440) = {sf(3 / 880)} s', ['C1: ω = 2πf', 'C1: t = Δφ/ω'], aq='t')
N('M', 4, 'A swing has natural angular frequency 2.1 rad s⁻¹. A child pushes it every 6.0 s. Calculate the swing\'s natural period, and how many swings it makes between pushes. Give the number of swings.', 6.0 / (2 * pi / 2.1), None, f'T = 2π ÷ 2.1 = {sf(2 * pi / 2.1)} s. Swings between pushes = 6.0 ÷ {sf(2 * pi / 2.1, 4)} = {sf(6 / (2 * pi / 2.1))}: each push still lands at the same point of the cycle, so energy is still added.', ['C1: T = 2π/ω', 'C1: ratio', 'B1: whole number of cycles'], aq='swings', tol=0.03)
# hard
N('H', 5, 'A small boat bobs with s.h.m. when a wave passes. The boat\'s mass is 300 kg and the extra upthrust per metre of extra depth is 1.2 × 10⁴ N m⁻¹. (a) Calculate the angular frequency. (b) Calculate the period. (c) Explain why a heavier boat of the same shape bobs more slowly. Give only the answer to (b).', 2 * pi * sqrt(300 / 1.2e4), 's',
  f'(a) ω = √(k/m) = √(1.2 × 10⁴ ÷ 300) = {sf(sqrt(40))} rad s⁻¹. (b) T = 2π/ω = 2π ÷ {sf(sqrt(40), 4)} = {sf(2 * pi / sqrt(40))} s. (c) Same k but larger m, so ω = √(k/m) is smaller and the period longer.',
  ['C1: ω = √(k/m)', 'A1: ω', 'C1: T = 2π/ω', 'A1: T', 'B1: larger m, smaller ω'], aq='T')
N('H', 6, 'A student measures the period of a pendulum for two lengths: L = 0.50 m, T = 1.42 s; L = 1.50 m, T = 2.46 s. (a) Calculate ω for each. (b) Show that ω²L is approximately constant. (c) Use the mean value of ω²L to find g. Give only the answer to (c).', ((2 * pi / 1.42) ** 2 * 0.50 + (2 * pi / 2.46) ** 2 * 1.50) / 2, 'N kg⁻¹',
  f'(a) ω₁ = 2π ÷ 1.42 = {sf(2 * pi / 1.42)} rad s⁻¹, ω₂ = 2π ÷ 2.46 = {sf(2 * pi / 2.46)} rad s⁻¹. (b) ω₁²L₁ = {sf((2 * pi / 1.42) ** 2 * 0.5)}, ω₂²L₂ = {sf((2 * pi / 2.46) ** 2 * 1.5)}: nearly equal. (c) g = ({sf((2 * pi / 1.42) ** 2 * 0.5, 4)} + {sf((2 * pi / 2.46) ** 2 * 1.5, 4)}) ÷ 2 = {sf(((2 * pi / 1.42) ** 2 * 0.5 + (2 * pi / 2.46) ** 2 * 1.5) / 2)} N kg⁻¹',
  ['C1: ω = 2π/T', 'A1: both ω', 'M1: ω²L for both', 'A1: approximately constant', 'C1: mean', 'A1: g'], aq='g')
N('H', 5, 'Two springs, each of constant 80 N m⁻¹, are joined end to end (in series) and support a 0.40 kg mass. In series the combined constant is half of one spring\'s. (a) Calculate the combined spring constant. (b) Calculate ω. (c) Calculate the frequency and compare it with a single spring. Give only the frequency in (c).', sqrt(40 / 0.40) / (2 * pi), 'Hz',
  f'(a) k = 80 ÷ 2 = 40 N m⁻¹. (b) ω = √(40 ÷ 0.40) = 10 rad s⁻¹. (c) f = 10 ÷ 2π = {sf(10 / (2 * pi))} Hz; with one spring f = √(80 ÷ 0.40) ÷ 2π = {sf(sqrt(200) / (2 * pi))} Hz, which is √2 times higher.',
  ['A1: k = 40 N m⁻¹', 'C1: ω = √(k/m)', 'A1: ω', 'C1: f = ω/2π', 'A1: f and comparison'], aq='f')
N('H', 6, 'A mass–spring system oscillates at 3.0 Hz. When an extra 0.10 kg is added the frequency falls to 2.5 Hz. (a) Show that m₁f₁² = m₂f₂² for the same spring. (b) Calculate the original mass. (c) Calculate the spring constant. Give only the answer to (b).', 0.10 * 2.5 ** 2 / (3.0 ** 2 - 2.5 ** 2), 'kg',
  f'(a) f = (1/2π)√(k/m), so mf² = k/4π², a constant. (b) m × 3.0² = (m + 0.10) × 2.5², so m(9.0 − 6.25) = 0.625 and m = 0.625 ÷ 2.75 = {sf(0.625 / 2.75)} kg. (c) k = 4π²mf² = 4π² × {sf(0.625 / 2.75, 4)} × 3.0² = {sf(4 * pi ** 2 * 0.625 / 2.75 * 9)} N m⁻¹',
  ['M1: mf² constant', 'A1: shown', 'C1: equation in m', 'A1: m', 'C1: k = 4π²mf²', 'A1: k'], aq='m')
N('H', 5, 'A metronome\'s arm behaves like a pendulum with an adjustable weight. At one setting it ticks 92 times per minute, one tick each half-swing. (a) Calculate the period of the arm. (b) Calculate ω. (c) The weight is moved so the period becomes 1.5 times longer. Calculate the new number of ticks per minute. Give only the answer to (c).', 92 / 1.5, None,
  f'(a) 92 ticks = 46 oscillations per minute, T = 60 ÷ 46 = {sf(60 / 46)} s. (b) ω = 2π ÷ {sf(60 / 46, 4)} = {sf(2 * pi / (60 / 46))} rad s⁻¹. (c) A longer period means fewer ticks: 92 ÷ 1.5 = {sf(92 / 1.5)} ticks per minute',
  ['M1: two ticks per oscillation', 'A1: T', 'A1: ω', 'C1: ticks ∝ 1/T', 'A1: ticks'], aq='ticks')
N('H', 6, 'In an atomic force microscope, a tiny cantilever of effective mass 2.5 × 10⁻¹¹ kg vibrates at 160 kHz. (a) Calculate ω. (b) Calculate the effective spring constant. (c) A particle of mass 1.0 × 10⁻¹⁵ kg sticks to it. Calculate the change in frequency. Give only the answer to (c).',
  160e3 - sqrt((2.5e-11 * (2 * pi * 160e3) ** 2) / (2.5e-11 + 1e-15)) / (2 * pi), 'Hz',
  f'(a) ω = 2π × 1.60 × 10⁵ = {sf(2 * pi * 1.6e5)} rad s⁻¹. (b) k = mω² = 2.5 × 10⁻¹¹ × ({sf(2 * pi * 1.6e5)})² = {sf(2.5e-11 * (2 * pi * 1.6e5) ** 2)} N m⁻¹. (c) f ∝ 1/√m: new f = 1.60 × 10⁵ × √(2.5 × 10⁻¹¹ ÷ 2.5001 × 10⁻¹¹) = {sf(1.6e5 * sqrt(2.5e-11 / (2.5e-11 + 1e-15)), 6)} Hz. The fall = 1.60 × 10⁵ × (1 − √(2.5 × 10⁻¹¹ ÷ 2.5001 × 10⁻¹¹)) = {sf(160e3 - 1.6e5 * sqrt(2.5e-11 / (2.5e-11 + 1e-15)))} Hz',
  ['C1: ω = 2πf', 'A1: ω', 'C1: k = mω²', 'A1: k', 'C1: f ∝ 1/√m', 'A1: Δf'], sig=2, aq='Δf')
N('H', 5, 'A pendulum clock\'s pendulum has ω = 3.1416 rad s⁻¹ (period 2.000 s). (a) Calculate its length using g = 9.81 N kg⁻¹. (b) The length is increased by 1.0 mm. Calculate the new period. (c) Calculate how many seconds the clock loses per day. Give only the answer to (c).', 86400 * (1 - 2.0 / (2 * pi * sqrt((9.81 / pi ** 2 + 0.001) / 9.81))), 's',
  f'(a) L = g/ω² = 9.81 ÷ 3.1416² = {sf(9.81 / pi ** 2, 4)} m. (b) T = 2π × √({sf(9.81 / pi ** 2 + 0.001, 5)} ÷ 9.81) = {sf(2 * pi * sqrt((9.81 / pi ** 2 + 0.001) / 9.81), 6)} s. (c) Seconds lost = 86400 × (1 − 2.000 ÷ {sf(2 * pi * sqrt((9.81 / pi ** 2 + 0.001) / 9.81), 6)}) = {sf(86400 * (1 - 2.0 / (2 * pi * sqrt((9.81 / pi ** 2 + 0.001) / 9.81))))} s',
  ['C1: L = g/ω²', 'A1: L', 'A1: new T', 'M1: fraction lost × 86 400', 'A1: seconds lost'], aq='loss')
N('H', 6, 'A U-shaped tube holds water; the liquid column (length 0.40 m) oscillates with ω² = 2g/L. A second tube holds a column 0.90 m long. (a) Calculate ω for each. (b) Calculate the ratio of their periods. (c) Explain why changing the liquid to oil does not change ω. Give only the ratio (longer/shorter) in (b).', sqrt(0.90 / 0.40), None,
  f'(a) ω₁ = √(2 × 9.81 ÷ 0.40) = {sf(sqrt(2 * 9.81 / 0.4))} rad s⁻¹, ω₂ = √(2 × 9.81 ÷ 0.90) = {sf(sqrt(2 * 9.81 / 0.9))} rad s⁻¹. (b) T ∝ √L: ratio = √(0.90 ÷ 0.40) = {sf(1.5, 2)}. (c) Both the restoring force and the mass of liquid are proportional to its density, which cancels.',
  ['C1: ω² = 2g/L', 'A1: both ω', 'C1: T ∝ √L', 'A1: ratio', 'B1: density cancels', 'B1: reason'], sig=2, aq='ratio')
N('H', 5, 'A spring–mass system has ω = 8.0 rad s⁻¹. The spring is cut in half and the same mass hung from one half (each half has twice the spring constant). (a) Calculate the new ω. (b) Calculate the new period. (c) State the ratio of new frequency to old. Give only the answer to (b).', 2 * pi / (8.0 * sqrt(2)), 's',
  f'(a) ω ∝ √k: ω = 8.0 × √2 = {sf(8 * sqrt(2))} rad s⁻¹. (b) T = 2π ÷ {sf(8 * sqrt(2), 4)} = {sf(2 * pi / (8 * sqrt(2)))} s. (c) √2 = 1.41.',
  ['M1: k doubles', 'C1: ω ∝ √k', 'A1: ω', 'A1: T', 'B1: √2'], aq='T')
N('H', 6, 'An astronaut finds that a 1.00 kg mass on a spring oscillates at 1.25 Hz on Earth and also at 1.25 Hz on a moon, while a 1.00 m pendulum has ω = 3.13 rad s⁻¹ on Earth and 1.42 rad s⁻¹ on the moon. (a) Explain why the spring frequency is the same in both places. (b) Calculate g on the moon. (c) Calculate the spring constant. Give only the answer to (b).', 1.42 ** 2 * 1.00, 'N kg⁻¹',
  f'(a) ω = √(k/m) has no g in it. (b) ω² = g/L: g = ω²L = 1.42² × 1.00 = {sf(1.42 ** 2)} N kg⁻¹. (c) k = m(2πf)² = 1.00 × (2π × 1.25)² = {sf((2.5 * pi) ** 2)} N m⁻¹',
  ['B1: no g in spring ω', 'C1: g = ω²L', 'A1: g', 'C1: k = mω²', 'C1: ω = 2πf', 'A1: k'], aq='g')
N('H', 5, 'A tall chimney sways with period 2.2 s. An engineer fits a damper and the effective mass doubles while the stiffness rises by 50 %. (a) Calculate the original ω. (b) Calculate the new ω. (c) Calculate the new period. Give only the answer to (c).', 2.2 * sqrt(2 / 1.5), 's',
  f'(a) ω = 2π ÷ 2.2 = {sf(2 * pi / 2.2)} rad s⁻¹. (b) ω ∝ √(k/m): ω = {sf(2 * pi / 2.2)} × √(1.5 ÷ 2) = {sf(2 * pi / 2.2 * sqrt(0.75))} rad s⁻¹. (c) T = 2π ÷ {sf(2 * pi / 2.2 * sqrt(0.75), 4)} = {sf(2.2 / sqrt(0.75))} s',
  ['C1: ω = 2π/T', 'A1: original ω', 'C1: ω ∝ √(k/m)', 'A1: new ω', 'A1: new T'], aq='T')

# ═════════════════════════ 18.7 Equations of s.h.m. (need 17/18/9) ═════════════════════════
lesson('18.7')
N('E', 2, 'An oscillator obeys x = 0.030 cos(20t) m. Calculate its displacement at t = 0.', 0.030, 'm', 'At t = 0, cos 0 = 1, so x = 0.030 × 1 = 0.030 m', ['C1: substitute t = 0'], sig=2, aq='x')
N('E', 2, 'An oscillator obeys x = 0.050 sin(10t) m. Calculate its maximum speed.', 0.050 * 10, 'm s⁻¹', 'v_max = ωx₀ = 10 × 0.050 = 0.50 m s⁻¹', ['C1: v_max = ωx₀'], sig=2, aq='v_max')
M('E', 1, 'An object starts from its equilibrium position at t = 0 and oscillates with amplitude x₀. Which equation describes its displacement?', 'x = x₀ sin ωt', ['x = x₀ cos ωt', 'x = x₀ tan ωt', 'x = x₀ ωt'], 'sin 0 = 0, so x = x₀ sin ωt starts at equilibrium.')
M('E', 1, 'Which equation gives the speed of an s.h.m. object at displacement x?', 'v = ω√(x₀² − x²)', ['v = ω(x₀ − x)', 'v = ω²x', 'v = ωx'], 'From energy or calculus: v² = ω²(x₀² − x²).')
N('E', 2, 'For x = 0.040 sin(6.0t) m, calculate the maximum acceleration.', 6.0 ** 2 * 0.040, 'm s⁻²', 'a_max = ω²x₀ = 6.0² × 0.040 = 1.44 m s⁻²', ['C1: a_max = ω²x₀'], aq='a_max')
N('E', 2, 'An s.h.m. has ω = 5.0 rad s⁻¹ and amplitude 0.10 m. Calculate its speed when x = 0.060 m.', 5.0 * sqrt(0.10 ** 2 - 0.060 ** 2), 'm s⁻¹', 'v = ω√(x₀² − x²) = 5.0 × √(0.10² − 0.060²) = 0.40 m s⁻¹', ['C1: v = ω√(x₀² − x²)'], sig=2, aq='v')
M('E', 1, 'For x = x₀ cos ωt, which equation gives the velocity?', 'v = −ωx₀ sin ωt', ['v = ωx₀ cos ωt', 'v = −ω²x₀ cos ωt', 'v = x₀ sin ωt'], 'v = dx/dt = −ωx₀ sin ωt.')
N('E', 2, 'An oscillator obeys x = 0.025 sin(4πt) m. Calculate its frequency.', 2.0, 'Hz', 'ω = 4π rad s⁻¹, so f = ω/2π = 4π ÷ 2π = 2.0 Hz', ['C1: f = ω/2π'], sig=2, aq='f')
N('E', 2, 'For x = 0.080 cos(2.5t) m, what is the period?', 2 * pi / 2.5, 's', f'T = 2π/ω = 2π ÷ 2.5 = {sf(2 * pi / 2.5)} s', ['C1: T = 2π/ω'], aq='T')
M('E', 1, 'In x = x₀ sin ωt, what does x₀ represent?', 'The amplitude', ['The angular frequency', 'The period', 'The initial velocity'], 'x₀ is the maximum value of x, reached when sin ωt = ±1.')
N('E', 2, 'An object in s.h.m. has amplitude 0.20 m and ω = 3.0 rad s⁻¹. Calculate its speed at the equilibrium position.', 0.60, 'm s⁻¹', 'At x = 0, v = ωx₀ = 3.0 × 0.20 = 0.60 m s⁻¹', ['C1: v = ωx₀ at x = 0'], sig=2, aq='v')
N('E', 2, 'For a = −ω²x with ω = 7.0 rad s⁻¹, calculate the acceleration at x = −0.020 m.', 7.0 ** 2 * 0.020, 'm s⁻²', 'a = −ω²x = −49 × (−0.020) = +0.98 m s⁻²', ['C1: a = −ω²x with sign'], sign=True, aq='a')
M('E', 1, 'An oscillator obeys x = 0.10 cos(πt) m. Where is it at t = 1.0 s?', 'At x = −0.10 m', ['At x = 0', 'At x = +0.10 m', 'At x = 0.05 m'], 'cos(π) = −1, so x = −0.10 m: the opposite extreme.')
M('E', 1, 'An s.h.m. obeys x = x₀ sin ωt. At what time does it first reach its maximum displacement?', 't = π/(2ω)', ['t = π/ω', 't = 2π/ω', 't = 0'], 'sin ωt = 1 first when ωt = π/2, so t = π/(2ω) — a quarter period.')
N('E', 2, 'An oscillator obeys v = 0.12 cos(8.0t) m s⁻¹. Calculate its amplitude.', 0.12 / 8.0, 'm', 'v_max = ωx₀, so x₀ = 0.12 ÷ 8.0 = 0.015 m', ['C1: x₀ = v_max/ω'], sig=2, aq='x₀')
N('E', 2, 'A playground spring-rider rocks back and forth with s.h.m.: ω = 2.0 rad s⁻¹, amplitude 0.50 m. How fast is the seat moving when it is 0.30 m from its central position?', 2.0 * sqrt(0.25 - 0.09), 'm s⁻¹', 'v = ω√(x₀² − x²) = 2.0 × √(0.50² − 0.30²) = 0.80 m s⁻¹', ['C1: v = ω√(x₀² − x²)'], sig=2, aq='v')
M('E', 1, 'Which equation is NOT correct for s.h.m.?', 'v = ω²x', ['a = −ω²x', 'v_max = ωx₀', 'x = x₀ sin ωt'], 'v = ω²x is wrong: the speed is v = ω√(x₀² − x²), maximum ωx₀.')
N('E', 2, 'An oscillator obeys x = 0.060 sin(5.0t) m. Calculate x at t = 0.10 s.', 0.060 * sin(0.5), 'm', f'ωt = 0.50 rad = 28.6°. x = 0.060 × sin 28.6° = {sf(0.06 * sin(0.5))} m', ['C1: ωt in radians'], aq='x')
# medium
N('M', 3, 'A body moves with x = 0.15 cos(3.0t) m. Calculate its displacement, velocity and acceleration at t = 0.40 s. Give the velocity.', -0.15 * 3.0 * sin(1.2), 'm s⁻¹',
  f'ωt = 1.2 rad = 68.75°. x = 0.15 × cos 68.75° = {sf(0.15 * cos(1.2))} m. v = −0.15 × 3.0 × sin 68.75° = {sf(-0.45 * sin(1.2))} m s⁻¹. a = −ω²x = −9.0 × {sf(0.15 * cos(1.2))} = {sf(-9 * 0.15 * cos(1.2))} m s⁻²',
  ['C1: ωt in radians', 'C1: v = −ωx₀ sin ωt', 'C1: substitution'], sign=True, aq='v')
N('M', 3, 'An oscillator released from rest at x = +4.0 cm has period 1.6 s. Find the first time after release at which x = +2.0 cm.', (1.6 / (2 * pi)) * acos(0.5), 's',
  f'x = x₀ cos ωt: cos ωt = 0.5 gives ωt = π/3. ω = 2π ÷ 1.6, so t = (π/3) ÷ (2π ÷ 1.6) = 1.6 ÷ 6 = {sf(1.6 / 6)} s', ['C1: x = x₀ cos ωt', 'C1: ωt = π/3', 'C1: t = (π/3)/ω'], aq='t')
N('M', 4, 'An s.h.m. has x = 0.040 sin(ωt) m with period 0.80 s. Calculate the speed at t = 0.10 s.', 0.040 * (2 * pi / 0.80) * cos(2 * pi / 0.80 * 0.10), 'm s⁻¹',
  f'ω = 2π ÷ 0.80 = {sf(2 * pi / 0.8)} rad s⁻¹. ωt = π/4 rad = 45°. v = ωx₀ cos ωt = {sf(2 * pi / 0.8)} × 0.040 × cos 45° = {sf(2 * pi / 0.8 * 0.04 * cos(pi / 4))} m s⁻¹',
  ['C1: ω = 2π/T', 'C1: v = ωx₀ cos ωt', 'C1: ωt = 45°', ], aq='v')
M('M', 3, 'An s.h.m. obeys x = x₀ sin ωt. At what displacement is the speed equal to half the maximum speed?', '±(√3/2)x₀', ['±x₀/2', '±x₀/√2', '±x₀/4'], 'v = ω√(x₀² − x²) = ωx₀/2 gives x² = ¾x₀².', ['C1: v expression', 'C1: solve'])
N('M', 3, 'An oscillator has v_max = 0.30 m s⁻¹ and ω = 6.0 rad s⁻¹. Calculate its speed at a displacement of 4.0 cm.', 6.0 * sqrt(0.05 ** 2 - 0.04 ** 2), 'm s⁻¹', f'x₀ = v_max/ω = 0.30 ÷ 6.0 = 0.050 m. v = ω√(x₀² − x²) = 6.0 × √(0.050² − 0.040²) = {sf(6 * 0.03)} m s⁻¹', ['C1: x₀ = v_max/ω', 'C1: v formula', 'C1: substitution'], sig=2, aq='v')
N('M', 4, 'A mass oscillates with x = 0.12 sin(2πft) m and f = 0.50 Hz. Calculate how long it takes to move from x = 0 to x = 0.060 m.', (1 / (2 * pi * 0.5)) * asin(0.5), 's',
  f'sin(2πft) = 0.060 ÷ 0.12 = 0.50, so 2πft = π/6 and t = (π/6) ÷ (2π × 0.50) = {sf((pi / 6) / pi)} s', ['C1: sin ωt = 0.5', 'C1: ωt = π/6', 'C1: t'], aq='t')
M('M', 3, 'For x = 0.20 cos(5t) m, at which first time after t = 0 is the object at equilibrium?', 'π/10 s', ['π/5 s', '2π/5 s', '0.20 s'], 'cos 5t = 0 first at 5t = π/2, so t = π/10 s ≈ 0.31 s.', ['C1: cos = 0', 'C1: 5t = π/2'])
N('M', 3, 'An oscillator obeys a = −0.80 sin(4.0t) m s⁻². Calculate the displacement at t = 0.25 s.', (0.80 / 16) * sin(1.0), 'm', f'a = −ω²x, so x = (0.80 ÷ 4.0²) sin(4.0t) = 0.050 sin(4.0t) m. At t = 0.25 s, 4.0t = 1.0 rad = 57.3°: x = 0.050 × sin 57.3° = {sf(0.05 * sin(1.0))} m', ['C1: x₀ = a_max/ω²', 'C1: x expression', 'C1: substitution in radians'], aq='x')
N('M', 4, 'A pendulum of length 0.75 m is released from 5.0 cm to one side. Write an equation for its displacement and use it to find x at t = 0.30 s.' + take('g'), 0.050 * cos(sqrt(9.81 / 0.75) * 0.30), 'm',
  f'ω = √(g/L) = √(9.81 ÷ 0.75) = {sf(sqrt(9.81 / 0.75))} rad s⁻¹. x = 0.050 cos(ωt). ωt = {sf(sqrt(9.81 / 0.75) * 0.3)} rad = {sf(degrees(sqrt(9.81 / 0.75) * 0.3))}°: x = 0.050 × cos {sf(degrees(sqrt(9.81 / 0.75) * 0.3))}° = {sf(0.05 * cos(sqrt(9.81 / 0.75) * 0.3))} m',
  ['C1: ω = √(g/L)', 'C1: x = x₀ cos ωt (released from rest)', 'C1: substitution', ], aq='x')
M('M', 4, 'Which pair of equations describes an oscillator that starts at x = 0 moving in the negative direction?', 'x = −x₀ sin ωt and v = −ωx₀ cos ωt', ['x = x₀ sin ωt and v = ωx₀ cos ωt', 'x = x₀ cos ωt and v = −ωx₀ sin ωt', 'x = −x₀ cos ωt and v = ωx₀ sin ωt'], 'At t = 0: x = 0, v = −ωx₀ (negative, maximum). Only the first pair gives this.', ['C1: x = 0 at t = 0', 'C1: v negative at t = 0', 'C1: consistent derivative'])
N('M', 3, 'For s.h.m. with amplitude 6.0 cm, at what displacement is the speed 80 % of the maximum?', 0.060 * sqrt(1 - 0.8 ** 2), 'm', 'v/v_max = √(1 − x²/x₀²) = 0.80, so x = x₀√(1 − 0.64) = 0.060 × 0.60 = 0.036 m', ['C1: v/v_max = √(1 − x²/x₀²)', 'C1: solve'], sig=2, aq='x')
N('M', 4, 'A mass on a spring oscillates with x = 0.050 cos(12t) m. Calculate the time taken to move from x = +0.050 m to x = −0.025 m.', (1 / 12) * acos(-0.5), 's',
  f'cos 12t = −0.025 ÷ 0.050 = −0.50, so 12t = 2π/3 and t = (2π/3) ÷ 12 = {sf((2 * pi / 3) / 12)} s', ['C1: cos 12t = −0.5', 'C1: 12t = 2π/3', 'C1: t'], aq='t')
M('M', 3, 'An oscillator is at x = +x₀ at t = 0. Which equation gives its acceleration?', 'a = −ω²x₀ cos ωt', ['a = ω²x₀ cos ωt', 'a = −ω²x₀ sin ωt', 'a = ωx₀ cos ωt'], 'x = x₀ cos ωt, so a = −ω²x = −ω²x₀ cos ωt (negative maximum at t = 0).', ['C1: x = x₀ cos ωt', 'C1: a = −ω²x'])
N('M', 3, 'An oscillator obeys x = 0.090 sin(15t) m. Calculate its speed at x = 0.054 m.', 15 * sqrt(0.09 ** 2 - 0.054 ** 2), 'm s⁻¹', 'v = ω√(x₀² − x²) = 15 × √(0.090² − 0.054²) = 15 × 0.072 = 1.08 m s⁻¹', ['C1: ω and x₀ read from equation', 'C1: v formula'], aq='v')
N('M', 4, 'A body in s.h.m. passes through equilibrium at 0.60 m s⁻¹ and has period 1.2 s. Write an equation for x and calculate x at t = 0.20 s after passing through equilibrium.', (0.60 / (2 * pi / 1.2)) * sin(2 * pi / 1.2 * 0.20), 'm',
  f'ω = 2π ÷ 1.2 = {sf(2 * pi / 1.2)} rad s⁻¹, x₀ = 0.60 ÷ ω = {sf(0.6 / (2 * pi / 1.2))} m. x = x₀ sin ωt. ωt = π/3 rad = 60°: x = {sf(0.6 / (2 * pi / 1.2), 4)} × sin 60° = {sf(0.6 / (2 * pi / 1.2) * sin(pi / 3))} m',
  ['C1: x₀ = v_max/ω', 'C1: x = x₀ sin ωt', 'C1: substitution'], aq='x')
M('M', 3, 'For s.h.m., which graph of v² against x² is a straight line?', 'One with negative gradient −ω² and intercept ω²x₀²', ['One through the origin with gradient ω²', 'A horizontal line', 'One with positive gradient ω²'], 'v² = ω²x₀² − ω²x²: linear in x² with gradient −ω².', ['C1: v² = ω²(x₀² − x²)', 'C1: negative gradient'])
N('M', 3, 'A graph of v² against x² for an oscillator is a straight line from (0, 0.36 m² s⁻²) to (0.0025 m², 0). Calculate ω and the amplitude. Give ω.', sqrt(0.36 / 0.0025), 'rad s⁻¹', f'Gradient = −0.36 ÷ 0.0025 = −144 s⁻², which is −ω², so ω = √144 = 12 rad s⁻¹. x₀² = 0.0025 m², x₀ = 0.050 m.', ['C1: gradient = −ω²', 'C1: x-intercept = x₀²'], sig=2, aq='ω')
N('M', 3, 'An oscillator has period 0.50 s and amplitude 3.0 cm. Calculate its acceleration 0.050 s after passing through +x₀.', -(2 * pi / 0.5) ** 2 * 0.030 * cos(2 * pi / 0.5 * 0.05), 'm s⁻²',
  f'x = x₀ cos ωt with ω = 4π rad s⁻¹. ωt = 0.2π rad = 36°. a = −ω²x₀ cos ωt = −(4π)² × 0.030 × cos 36° = {sf(-(4 * pi) ** 2 * 0.03 * cos(radians(36)))} m s⁻²', ['C1: x = x₀ cos ωt', 'C1: a = −ω²x', 'C1: substitution'], sign=True, aq='a')
# hard
N('H', 6, 'A 0.25 kg mass oscillates on a spring with x = 0.080 cos(10t) m. (a) Calculate the spring constant. (b) Calculate the speed at t = 0.12 s. (c) Calculate the resultant force on the mass at that instant. Give only the answer to (c).', -0.25 * 100 * 0.080 * cos(1.2), 'N',
  f'(a) k = mω² = 0.25 × 10² = 25 N m⁻¹. (b) ωt = 1.2 rad = 68.75°: v = 10 × 0.080 × sin 68.75° = {sf(0.8 * sin(1.2))} m s⁻¹. (c) x = 0.080 × cos 68.75° = {sf(0.08 * cos(1.2))} m, F = −kx = −25 × {sf(0.08 * cos(1.2))} = {sf(-25 * 0.08 * cos(1.2))} N',
  ['C1: k = mω²', 'A1: k', 'C1: speed at t', 'A1: v', 'C1: F = −kx', 'A1: F with sign'], sign=True, aq='F')
N('H', 5, 'An object performs s.h.m. of period 2.0 s and amplitude 10 cm, starting at x = 0 at t = 0. (a) Write x(t). (b) Calculate the time taken to go from x = 0 to x = 5.0 cm. (c) Calculate the time taken to go from x = 5.0 cm to x = 10 cm, and explain why it is longer. Give only the answer to (c).', 0.5 - (1 / pi) * asin(0.5), 's',
  f'(a) x = 0.10 sin(πt) m. (b) sin(πt) = 0.5: πt = π/6, t = 1/6 = 0.167 s. (c) 0 to 10 cm takes T/4 = 0.50 s, so 5 to 10 cm takes 0.50 − 0.167 = {sf(0.5 - 1 / 6)} s: the object slows as it approaches the extreme.',
  ['B1: x = 0.10 sin πt', 'C1: sin πt = 0.5', 'A1: 0.167 s', 'C1: T/4 − 0.167', 'A1: 0.333 s and reason'], aq='t')
N('H', 6, 'A mass on a spring has a = −64x (SI units). It is released from rest at x = 0.050 m. (a) Calculate ω and the period. (b) Calculate the speed when x = 0.030 m. (c) Calculate the time taken to reach x = 0.030 m for the first time. Give only the answer to (c).', (1 / 8) * acos(0.6), 's',
  f'(a) ω = 8.0 rad s⁻¹, T = 2π ÷ 8.0 = {sf(2 * pi / 8)} s. (b) v = 8.0 × √(0.050² − 0.030²) = 0.32 m s⁻¹. (c) x = 0.050 cos 8t: cos 8t = 0.60, 8t = cos⁻¹ 0.60 = 53.13° = 0.927 rad, t = 0.927 ÷ 8.0 = {sf(acos(0.6) / 8)} s',
  ['A1: ω and T', 'C1: v = ω√(x₀² − x²)', 'A1: v', 'C1: cos 8t = 0.6', 'C1: inverse cosine in radians', 'A1: t'], aq='t')
N('H', 5, 'Derive v = ±ω√(x₀² − x²) from x = x₀ sin ωt and v = ωx₀ cos ωt, then use it. (a) Show the derivation. (b) For x₀ = 0.20 m and ω = 4.0 rad s⁻¹, find the speed at x = 0.12 m. (c) Find the two times in the first cycle at which x = +0.12 m. Give only the speed in (b).', 4.0 * sqrt(0.04 - 0.0144), 'm s⁻¹',
  f'(a) cos ωt = ±√(1 − sin²ωt) = ±√(1 − x²/x₀²), so v = ±ωx₀√(1 − x²/x₀²) = ±ω√(x₀² − x²). (b) v = 4.0 × √(0.20² − 0.12²) = 0.64 m s⁻¹. (c) sin 4t = 0.60: 4t = 0.6435 rad or π − 0.6435 rad, so t = 0.161 s or 0.625 s.',
  ['M1: sin² + cos² = 1', 'A1: derivation', 'C1: substitution', 'A1: v', 'B1: both times'], sig=2, aq='v')
N('H', 6, 'A buoy moves up and down with s.h.m. as waves pass: amplitude 0.60 m, period 5.0 s. A sensor on the buoy can only work when the buoy is at least 0.30 m above its mean level. (a) Write y(t), with y = 0 rising at t = 0. (b) Find the times in the first cycle when y = 0.30 m. (c) Calculate the time per cycle that the sensor works. Give only the answer to (c).', 5.0 / (2 * pi) * (pi - 2 * asin(0.5)), 's',
  f'(a) y = 0.60 sin(2πt/5.0) m. (b) sin(2πt/5) = 0.5 at 2πt/5 = π/6 and 5π/6: t = 0.417 s and 2.08 s. (c) working time = 2.08 − 0.417 = {sf(5 / (2 * pi) * (pi - pi / 3))} s per cycle (one third of the period).',
  ['B1: y = 0.60 sin(2πt/5)', 'C1: sin = 0.5', 'A1: both times', 'M1: difference', 'A1: time', 'B1: fraction of period'], aq='t')
N('H', 5, 'An oscillator has displacement x = 0.10 sin(2.0t) + 0.10 cos(2.0t) m. (a) Show that this is s.h.m. with ω = 2.0 rad s⁻¹ by finding a. (b) Show that the amplitude is 0.10√2 m. (c) Calculate the maximum speed. Give only the answer to (c).', 2.0 * 0.10 * sqrt(2), 'm s⁻¹',
  f'(a) a = −4.0 × (0.10 sin 2t + 0.10 cos 2t) = −4.0x, so a = −ω²x with ω = 2.0 rad s⁻¹. (b) The sum equals 0.10√2 sin(2t + π/4), so x₀ = 0.10 × √2 = {sf(0.1 * sqrt(2))} m. (c) v_max = ωx₀ = 2.0 × {sf(0.1 * sqrt(2), 4)} = {sf(0.2 * sqrt(2))} m s⁻¹',
  ['M1: second derivative', 'A1: a = −4x', 'B1: amplitude √2 × 0.10', 'C1: v_max = ωx₀', 'A1: v_max'], aq='v_max')

# ═════════════════════════ 18.8 Energy in simple harmonic motion (need 16/17/9) ═════════════════════════
lesson('18.8')
N('E', 2, 'A 0.40 kg mass oscillates with ω = 5.0 rad s⁻¹ and amplitude 0.10 m. Calculate its total energy.', 0.5 * 0.40 * 25 * 0.01, 'J', 'E = ½mω²x₀² = 0.5 × 0.40 × 5.0² × 0.10² = 0.050 J', ['C1: E = ½mω²x₀²'], sig=2, aq='E')
N('E', 2, 'A 2.0 kg mass oscillating with s.h.m. has a maximum speed of 0.30 m s⁻¹. Calculate its maximum kinetic energy.', 0.5 * 2.0 * 0.09, 'J', 'Ek = ½mv_max² = 0.5 × 2.0 × 0.30² = 0.090 J', ['C1: Ek = ½mv²'], sig=2, aq='Ek')
M('E', 1, 'In s.h.m., where is the potential energy (for a spring) greatest?', 'At maximum displacement', ['At the equilibrium position', 'Halfway to maximum displacement', 'It is the same everywhere'], 'Ep = ½kx² is greatest at x = ±x₀, where the speed (and Ek) is zero.')
M('E', 1, 'For an undamped oscillator, how does the total energy change during one cycle?', 'It stays constant', ['It is greatest at the centre', 'It is greatest at the extremes', 'It falls steadily'], 'Energy is transferred between Ek and Ep, but with no damping the total stays constant.')
M('E', 1, 'The amplitude of an oscillator is tripled at the same frequency. By what factor does its total energy change?', '9', ['3', '6', '27'], 'E = ½mω²x₀² ∝ x₀²: 3² = 9.')
N('E', 2, 'A spring of constant 50 N m⁻¹ is stretched 0.12 m from equilibrium in an oscillation. Calculate the elastic potential energy there.', 0.5 * 50 * 0.12 ** 2, 'J', f'Ep = ½kx² = 0.5 × 50 × 0.12² = {sf(0.36, 2)} J', ['C1: Ep = ½kx²'], sig=2, aq='Ep')
N('E', 2, 'An oscillator has total energy 0.80 J. At one instant its kinetic energy is 0.30 J. Calculate its potential energy.', 0.50, 'J', 'Ep = E − Ek = 0.80 − 0.30 = 0.50 J', ['C1: E = Ek + Ep'], sig=2, aq='Ep')
M('E', 1, 'At what displacement in s.h.m. are the kinetic and potential energies equal?', 'x = ±x₀/√2', ['x = ±x₀/2', 'x = 0', 'x = ±x₀'], 'Ep = ½mω²x² equals half the total ½mω²x₀² when x² = x₀²/2.')
N('E', 2, 'A 0.050 kg mass on a spring has total energy 2.0 × 10⁻³ J. Calculate its maximum speed.', sqrt(2 * 2.0e-3 / 0.050), 'm s⁻¹', f'At equilibrium all energy is kinetic: v = √(2E/m) = √(2 × 2.0 × 10⁻³ ÷ 0.050) = {sf(sqrt(0.08))} m s⁻¹', ['C1: E = ½mv_max²'], aq='v_max')
M('E', 1, 'What happens to the kinetic energy of a pendulum bob as it swings from the lowest point to the highest point?', 'It decreases to zero', ['It increases to a maximum', 'It stays constant', 'It decreases to half its maximum'], 'At the top the bob is momentarily at rest, so Ek = 0; the energy is now all gravitational potential.')
N('E', 2, 'A pendulum bob of mass 0.20 kg rises 4.0 cm above its lowest point at each end of its swing. Calculate its maximum kinetic energy.' + take('g'), 0.20 * 9.81 * 0.040, 'J', f'Ek max = mgh = 0.20 × 9.81 × 0.040 = {sf(0.07848)} J', ['C1: Ek max = mgh'], aq='Ek')
M('E', 1, 'An oscillator\'s amplitude is halved. What fraction of its energy remains?', '¼', ['½', '1/8', '¾'], 'E = ½mω²x₀², so with ω unchanged E ∝ x₀². Halving x₀ gives (½)² = ¼ of the energy: three quarters has been lost, mostly to damping.')
N('E', 2, 'An oscillator has m = 0.30 kg, ω = 8.0 rad s⁻¹, x₀ = 0.050 m. Calculate its potential energy at x = 0.030 m.', 0.5 * 0.30 * 64 * 0.030 ** 2, 'J', f'Ep = ½mω²x² = 0.5 × 0.30 × 8.0² × 0.030² = {sf(0.5 * 0.3 * 64 * 0.0009)} J', ['C1: Ep = ½mω²x²'], aq='Ep')
M('E', 1, 'Which graph shape shows how the potential energy of a mass–spring oscillator varies with displacement?', 'A parabola, minimum zero at x = 0', ['A straight line through the origin', 'An inverted parabola, maximum at x = 0', 'A horizontal line'], 'Ep = ½kx²: a U-shaped parabola with its minimum at equilibrium.')
N('E', 2, 'A child on a swing (total mass 30 kg) passes the lowest point at 3.0 m s⁻¹. Calculate the total energy of the oscillation (taking Ep = 0 at the lowest point).', 0.5 * 30 * 9, 'J', 'E = ½mv² = 0.5 × 30 × 3.0² = 135 J', ['C1: E = ½mv_max²'], aq='E')
M('E', 1, 'How often does the kinetic energy of an oscillator of period T reach its maximum?', 'Twice every period', ['Once every period', 'Four times every period', 'Once every two periods'], 'Ek is maximum each time the object passes through equilibrium: twice per cycle.')
N('E', 2, 'An oscillating 0.10 kg mass has kinetic energy 0.020 J at a certain point. Calculate its speed there.', sqrt(2 * 0.020 / 0.10), 'm s⁻¹', f'v = √(2Ek/m) = √(2 × 0.020 ÷ 0.10) = {sf(sqrt(0.4))} m s⁻¹', ['C1: v = √(2Ek/m)'], aq='v')
# medium
N('M', 3, 'A 0.50 kg mass on a spring of constant 200 N m⁻¹ oscillates with amplitude 6.0 cm. Calculate its kinetic energy when the displacement is 4.0 cm.', 0.5 * 200 * (0.06 ** 2 - 0.04 ** 2), 'J', 'Ek = ½k(x₀² − x²) = 0.5 × 200 × (0.060² − 0.040²) = 0.20 J', ['C1: E = ½kx₀²', 'C1: Ek = E − ½kx²'], sig=2, aq='Ek')
N('M', 4, 'An oscillator has total energy 0.45 J, mass 0.20 kg and period 0.60 s. Calculate its amplitude.', sqrt(2 * 0.45 / (0.20 * (2 * pi / 0.60) ** 2)), 'm', f'ω = 2π ÷ 0.60 = {sf(2 * pi / 0.6)} rad s⁻¹. E = ½mω²x₀², so x₀ = √(2E/mω²) = √(2 × 0.45 ÷ (0.20 × {sf(2 * pi / 0.6, 4)}²)) = {sf(sqrt(0.9 / (0.2 * (2 * pi / 0.6) ** 2)))} m', ['C1: ω = 2π/T', 'C1: E = ½mω²x₀²', 'C1: rearranged'], aq='x₀')
M('M', 3, 'An undamped oscillator has total energy E. What is its kinetic energy when its displacement is half the amplitude?', '¾E', ['½E', '¼E', 'E'], 'Ep = ½kx² = ½k(x₀/2)² = ¼E, so Ek = E − ¼E = ¾E.', ['C1: Ep ∝ x²', 'C1: Ek = E − Ep'])
N('M', 3, 'A mass–spring system has total energy 0.16 J. The spring constant is 80 N m⁻¹. Calculate the amplitude.', sqrt(2 * 0.16 / 80), 'm', f'E = ½kx₀², x₀ = √(2E/k) = √(2 × 0.16 ÷ 80) = {sf(sqrt(0.004))} m', ['C1: E = ½kx₀²', 'C1: rearranged'], aq='x₀')
N('M', 3, 'A 1.5 kg mass oscillates with s.h.m. of frequency 2.0 Hz and amplitude 4.0 cm. Calculate its maximum kinetic energy.', 0.5 * 1.5 * (4 * pi) ** 2 * 0.04 ** 2, 'J', f'ω = 2π × 2.0 = {sf(4 * pi)} rad s⁻¹. Ek max = ½mω²x₀² = 0.5 × 1.5 × ({sf(4 * pi)})² × 0.040² = {sf(0.5 * 1.5 * (4 * pi) ** 2 * 0.0016)} J', ['C1: ω = 2πf', 'C1: Ek max = ½mω²x₀²', 'C1: x₀ in m'], aq='Ek')
M('M', 4, 'Two identical masses on identical springs oscillate. A has amplitude 2 cm, B has amplitude 4 cm. Which is correct?', 'B has 4 times the energy and twice the maximum speed of A; their periods are equal', ['B has twice the energy and the same maximum speed', 'B has 4 times the energy and 4 times the maximum speed', 'B has a longer period'], 'E ∝ x₀² (factor 4); v_max = ωx₀ (factor 2); T depends only on m and k.', ['C1: E ∝ x₀²', 'C1: v_max ∝ x₀', 'C1: T unchanged'])
N('M', 3, 'A pendulum of length 1.2 m and bob mass 0.40 kg swings with amplitude 8.0 cm. Using E = ½mω²x₀², calculate its energy.' + take('g'), 0.5 * 0.40 * (9.81 / 1.2) * 0.08 ** 2, 'J', f'ω² = g/L = 9.81 ÷ 1.2 = {sf(9.81 / 1.2)} s⁻². E = 0.5 × 0.40 × {sf(9.81 / 1.2, 4)} × 0.080² = {sf(0.2 * 9.81 / 1.2 * 0.0064)} J', ['C1: ω² = g/L', 'C1: E = ½mω²x₀²'], aq='E')
N('M', 4, 'A 0.20 kg mass oscillates with ω = 12 rad s⁻¹ and amplitude 0.050 m. Find the displacement at which its kinetic energy is three times its potential energy.', 0.050 / 2, 'm', 'Ek = 3Ep means Ep = ¼E: ½mω²x² = ¼ × ½mω²x₀², so x = x₀/2 = 0.050 ÷ 2 = 0.025 m', ['C1: Ep = E/4', 'C1: x² = x₀²/4', 'C1: x'], sig=2, aq='x')
M('M', 3, 'For an oscillator, a graph of kinetic energy against displacement is…', 'an inverted parabola, maximum at x = 0 and zero at x = ±x₀', ['a parabola with minimum zero at x = 0', 'a straight line', 'a constant'], 'Ek = ½mω²(x₀² − x²): an upside-down parabola.', ['C1: Ek = ½mω²(x₀² − x²)', 'C1: shape'])
N('M', 3, 'A spring–mass oscillator of total energy 0.090 J has amplitude 3.0 cm. Calculate the restoring force at maximum displacement.', 2 * 0.090 / 0.030, 'N', 'E = ½kx₀², so k = 2E/x₀² = 2 × 0.090 ÷ 0.030² = 200 N m⁻¹. F = kx₀ = 200 × 0.030 = 6.0 N', ['C1: k = 2E/x₀²', 'C1: F = kx₀'], sig=2, aq='F')
N('M', 3, 'A swing of mass 25 kg (with child) has period 3.5 s and amplitude 1.2 m. Calculate its total energy.', 0.5 * 25 * (2 * pi / 3.5) ** 2 * 1.2 ** 2, 'J', f'ω = 2π ÷ 3.5 = {sf(2 * pi / 3.5)} rad s⁻¹. E = ½mω²x₀² = 0.5 × 25 × ({sf(2 * pi / 3.5)})² × 1.2² = {sf(0.5 * 25 * (2 * pi / 3.5) ** 2 * 1.44)} J', ['C1: ω = 2π/T', 'C1: E formula'], aq='E')
M('M', 3, 'An oscillator of frequency 5.0 Hz is undamped. At what frequency does its potential energy vary?', '10 Hz', ['5.0 Hz', '2.5 Hz', '20 Hz'], 'Ep ∝ x² peaks at both extremes in each cycle, so it varies at twice the oscillation frequency.', ['C1: two maxima per cycle', 'C1: 2f'])
N('M', 4, 'A 0.60 kg mass oscillating with s.h.m. has speed 0.40 m s⁻¹ at x = 0.030 m and speed 0.20 m s⁻¹ at x = 0.050 m. Use energy conservation to find the spring constant.', 0.60 * (0.40 ** 2 - 0.20 ** 2) / (0.050 ** 2 - 0.030 ** 2), 'N m⁻¹',
  f'½mv₁² + ½kx₁² = ½mv₂² + ½kx₂², so k = m(v₁² − v₂²)/(x₂² − x₁²) = 0.60 × (0.40² − 0.20²) ÷ (0.050² − 0.030²) = {sf(0.6 * 0.12 / 0.0016)} N m⁻¹', ['C1: energy equation', 'C1: rearranged for k', 'C1: substitution'], aq='k')
N('M', 3, 'A mass on a spring has maximum kinetic energy 0.25 J. Calculate the kinetic energy when it is at 60 % of its amplitude.', 0.25 * (1 - 0.36), 'J', 'Ek = E(1 − x²/x₀²) = 0.25 × (1 − 0.60²) = 0.16 J', ['C1: Ek = E(1 − x²/x₀²)', 'C1: substitution'], sig=2, aq='Ek')
M('M', 3, 'Why is the total energy of a simple harmonic oscillator proportional to the square of the amplitude?', 'The maximum potential energy ½kx₀² depends on x₀²', ['The speed is proportional to x₀²', 'The period is proportional to x₀', 'The force is proportional to x₀²'], 'At the extremes all the energy is ½kx₀² (or ½mω²x₀²), so E ∝ x₀².', ['C1: E = ½kx₀²', 'C1: x₀² dependence'])
N('M', 3, 'A loudspeaker cone of mass 15 g vibrates at 200 Hz with amplitude 0.50 mm. Calculate its vibrational energy.', 0.5 * 0.015 * (400 * pi) ** 2 * 0.0005 ** 2, 'J', f'E = ½mω²x₀² = 0.5 × 0.015 × (2π × 200)² × (5.0 × 10⁻⁴)² = {sf(0.5 * 0.015 * (400 * pi) ** 2 * 2.5e-7)} J', ['C1: ω = 2πf', 'C1: E formula', 'C1: units'], aq='E')
N('M', 4, 'An oscillator\'s energy falls from 0.80 J to 0.20 J due to damping. The original amplitude was 10 cm. Calculate the new amplitude.', 0.10 * sqrt(0.20 / 0.80), 'm', 'E ∝ x₀²: x₀ = 0.10 × √(0.20 ÷ 0.80) = 0.050 m', ['C1: E ∝ x₀²', 'C1: ratio', 'C1: square root'], sig=2, aq='x₀')
# hard
N('H', 6, 'A 0.40 kg mass on a spring of constant 160 N m⁻¹ is pulled 5.0 cm from equilibrium and released on a frictionless surface. (a) Calculate the total energy. (b) Calculate the maximum speed. (c) Calculate the speed and kinetic energy when the displacement is 3.0 cm. Give only the kinetic energy in (c).', 0.5 * 160 * (0.05 ** 2 - 0.03 ** 2), 'J',
  f'(a) E = ½kx₀² = 0.5 × 160 × 0.050² = 0.20 J. (b) v_max = √(2E/m) = √(2 × 0.20 ÷ 0.40) = 1.0 m s⁻¹. (c) Ep = ½ × 160 × 0.030² = 0.072 J, Ek = 0.20 − 0.072 = {sf(0.128)} J, v = √(2 × 0.128 ÷ 0.40) = {sf(sqrt(0.64))} m s⁻¹',
  ['C1: E = ½kx₀²', 'A1: E', 'A1: v_max', 'C1: Ep at 3.0 cm', 'C1: Ek = E − Ep', 'A1: Ek'], aq='Ek')
N('H', 5, 'A pendulum bob of mass 0.25 kg on a 1.5 m string swings with amplitude 0.12 m. (a) Calculate ω. (b) Calculate the total energy using E = ½mω²x₀². (c) Calculate the height the bob rises above its lowest point and check against mgh. Give only the answer to (b).' + take('g'), 0.5 * 0.25 * (9.81 / 1.5) * 0.12 ** 2, 'J',
  f'(a) ω = √(g/L) = √(9.81 ÷ 1.5) = {sf(sqrt(9.81 / 1.5))} rad s⁻¹. (b) E = 0.5 × 0.25 × {sf(9.81 / 1.5, 4)} × 0.12² = {sf(0.125 * 9.81 / 1.5 * 0.0144)} J. (c) h ≈ x₀²/2L = 0.12² ÷ (2 × 1.5) = 4.8 × 10⁻³ m, mgh = 0.25 × 9.81 × 4.8 × 10⁻³ = {sf(0.25 * 9.81 * 0.0048)} J: the same.',
  ['C1: ω = √(g/L)', 'A1: ω', 'A1: E', 'C1: h = x₀²/2L', 'B1: mgh agrees'], aq='E')
N('H', 6, 'A graph shows the potential energy of an oscillating 0.10 kg mass against displacement: a parabola reaching 0.045 J at x = ±0.030 m. (a) Calculate the spring constant. (b) Calculate ω. (c) Calculate the speed of the mass at x = 0.010 m. Give only the answer to (c).', sqrt(2 * (0.045 - 0.5 * 100 * 0.01 ** 2) / 0.10), 'm s⁻¹',
  f'(a) ½kx₀² = 0.045, k = 2 × 0.045 ÷ 0.030² = 100 N m⁻¹. (b) ω = √(100 ÷ 0.10) = {sf(sqrt(1000))} rad s⁻¹. (c) Ep = ½ × 100 × 0.010² = 0.0050 J, Ek = 0.045 − 0.0050 = 0.040 J, v = √(2 × 0.040 ÷ 0.10) = {sf(sqrt(0.8))} m s⁻¹',
  ['C1: k from Ep graph', 'A1: k', 'A1: ω', 'C1: Ep at 0.010 m', 'C1: Ek = E − Ep', 'A1: v'], aq='v')
N('H', 5, 'A vertical spring (k = 40 N m⁻¹) has a 0.10 kg mass that oscillates with amplitude 4.0 cm. (a) Calculate the total oscillation energy. (b) Calculate the maximum speed. (c) Explain why gravitational potential energy does not need separate treatment if displacement is measured from the equilibrium position. Give only the answer to (b).', sqrt(40 / 0.10) * 0.040, 'm s⁻¹',
  f'(a) E = ½kx₀² = 0.5 × 40 × 0.040² = 0.032 J. (b) v_max = ωx₀ = √(40 ÷ 0.10) × 0.040 = {sf(20 * 0.04)} m s⁻¹. (c) Measured from equilibrium, the combined effect of gravity and the spring is a restoring force −kx, so the energy behaves as ½kx² alone.',
  ['A1: E', 'C1: ω = √(k/m)', 'A1: v_max', 'B1: equilibrium shifts', 'B1: net restoring force −kx'], aq='v_max')
N('H', 6, 'A 0.30 kg mass oscillates on a spring with total energy 0.12 J and period 0.40 s. (a) Calculate the amplitude. (b) Calculate the displacement at which Ek = Ep. (c) Calculate the time, after passing through equilibrium, at which Ek = Ep first. Give only the answer to (c).', 0.40 / 8, 's',
  f'(a) ω = 2π ÷ 0.40 = {sf(5 * pi)} rad s⁻¹, x₀ = √(2E/mω²) = √(2 × 0.12 ÷ (0.30 × {sf(5 * pi, 4)}²)) = {sf(sqrt(0.24 / (0.3 * (5 * pi) ** 2)))} m. (b) x = x₀/√2 = {sf(sqrt(0.24 / (0.3 * (5 * pi) ** 2)) / sqrt(2))} m. (c) x = x₀ sin ωt = x₀/√2 when ωt = π/4, t = T/8 = 0.40 ÷ 8 = 0.050 s',
  ['C1: ω', 'A1: x₀', 'C1: x = x₀/√2', 'A1: x', 'C1: ωt = π/4', 'A1: t'], sig=2, aq='t')
N('H', 5, 'A trolley of mass 0.80 kg between two springs oscillates with amplitude 8.0 cm and period 1.2 s. Its kinetic energy is recorded by a data logger. (a) Calculate the maximum kinetic energy. (b) State the period of the Ek–time graph. (c) Calculate the kinetic energy 0.15 s after the trolley passes through equilibrium. Give only the answer to (c).', 0.5 * 0.80 * (2 * pi / 1.2 * 0.08 * cos(2 * pi / 1.2 * 0.15)) ** 2, 'J',
  f'(a) v_max = ωx₀ = (2π ÷ 1.2) × 0.080 = {sf(2 * pi / 1.2 * 0.08)} m s⁻¹, Ek = ½ × 0.80 × {sf(2 * pi / 1.2 * 0.08, 4)}² = {sf(0.4 * (2 * pi / 1.2 * 0.08) ** 2)} J. (b) 0.60 s. (c) v = v_max cos ωt with ωt = 45°: Ek = Ek,max × cos² 45° = {sf(0.4 * (2 * pi / 1.2 * 0.08) ** 2, 4)} × 0.5 = {sf(0.2 * (2 * pi / 1.2 * 0.08) ** 2)} J',
  ['C1: v_max = ωx₀', 'A1: Ek max', 'B1: T/2', 'C1: ωt = π/4', 'A1: Ek'], aq='Ek')

# ═════════════════════════ 18.9 Damped oscillations (need 16/18/10) ═════════════════════════
lesson('18.9')
M('E', 1, 'A swinging pendulum gradually comes to rest. Which describes damping?', 'The loss of energy from an oscillating system, which reduces the amplitude', ['An increase in the frequency of an oscillation', 'The force that keeps an oscillation going', 'The transfer of energy into an oscillator by a driver'], 'Damping forces such as friction and air resistance transfer energy out of the system, so the amplitude decreases.')
M('E', 1, 'Which describes light damping?', 'The system oscillates with an amplitude that decreases gradually', ['The system returns to equilibrium in the shortest time without oscillating', 'The system returns to equilibrium very slowly without oscillating', 'The amplitude increases'], 'Light damping: many oscillations with a gradually decreasing amplitude (exponential decay).')
M('E', 1, 'What is critical damping?', 'Damping that returns the system to equilibrium in the shortest possible time without oscillating', ['Damping that stops oscillation instantly', 'Damping so heavy that the system never returns', 'Damping that makes the amplitude grow'], 'Critically damped systems do not overshoot and settle fastest. Overdamped ones are slower.')
M('E', 1, 'Which is an example of a system designed to be critically damped?', 'A car\'s suspension', ['A guitar string', 'A pendulum clock', 'A tuning fork'], 'A car body should settle quickly after a bump without bouncing.')
M('E', 1, 'What happens to the period of a lightly damped pendulum as its amplitude decreases?', 'It stays almost the same', ['It doubles', 'It falls to zero', 'It increases steadily'], 'Light damping has a negligible effect on the period.')
M('E', 1, 'What type of damping is shown by a system that returns to equilibrium very slowly without oscillating?', 'Overdamping (heavy damping)', ['Light damping', 'Critical damping', 'No damping'], 'Heavy damping prevents oscillation but makes the return slower than critical damping.')
N('E', 2, 'The amplitude of a damped oscillation falls from 12 cm to 9.0 cm. Calculate the fraction of the energy that remains.', (9 / 12) ** 2, None, 'E ∝ A²: fraction = (9.0 ÷ 12)² = 0.5625', ['C1: E ∝ A²'], aq='fraction')
N('E', 2, 'A damped oscillator loses 10 % of its amplitude every cycle. Starting at 20 cm, calculate its amplitude after 3 cycles.', 20 * 0.9 ** 3, 'cm', 'A = 20 × 0.90³ = 14.6 cm', ['C1: × 0.90 each cycle'], aq='A')
M('E', 1, 'What causes the damping of a swinging pendulum in air?', 'Air resistance on the bob and friction at the pivot', ['Gravity', 'The tension in the string', 'The mass of the bob'], 'Air resistance and friction do work against the motion, transferring energy to the surroundings as heat.')
M('E', 1, 'For a lightly damped oscillator, which graph shape describes amplitude against time?', 'An exponential decay curve', ['A straight line rising', 'A horizontal line', 'A sine curve of constant height'], 'With light damping the amplitude falls by the same fraction each cycle: an exponential decay.')
N('E', 2, 'A damped oscillator has energy 0.40 J. Its amplitude is reduced to half. Calculate its energy now.', 0.10, 'J', 'E ∝ A²: E = 0.40 × 0.5² = 0.10 J', ['C1: E ∝ A²'], sig=2, aq='E')
M('E', 1, 'Where does the energy lost by a damped oscillator go?', 'Mostly to internal (thermal) energy of the system and surroundings', ['It is destroyed', 'Into increasing the frequency', 'Into the gravitational potential energy of the Earth'], 'Energy is conserved: friction and drag transfer it to thermal energy (and some sound).')
N('E', 2, 'A pendulum\'s amplitude halves every 5 oscillations. Starting at 16 cm, what is its amplitude after 15 oscillations?', 16 / 8, 'cm', 'After 15 oscillations the amplitude has halved 3 times: 16 ÷ 2³ = 2.0 cm', ['C1: three halvings'], sig=2, aq='A')
M('E', 1, 'Shock absorbers in a car contain oil. What is their purpose?', 'To damp the oscillations of the car body on its springs', ['To increase the bounce of the car', 'To lubricate the wheels', 'To reduce the car\'s weight'], 'The oil\'s viscous drag removes energy from the oscillations so the car does not keep bouncing.')
N('E', 2, 'The amplitude of a damped oscillation decreases by 4.0 % each cycle. What percentage of the energy is lost each cycle?', (1 - 0.96 ** 2) * 100, '%', 'Energy fraction remaining = 0.96² = 0.9216, so the percentage lost = (1 − 0.9216) × 100 = 7.8 % each cycle', ['C1: E ∝ A²'], sig=2, aq='loss')
M('E', 1, 'Which graph shows critical damping after a system is displaced and released?', 'The displacement falls smoothly to zero in the shortest time, with no overshoot', ['The displacement oscillates with constant amplitude', 'The displacement oscillates with slowly decreasing amplitude', 'The displacement falls to zero very slowly'], 'Critical damping: quickest return to equilibrium without crossing it.')
# medium
N('M', 3, 'A lightly damped oscillator\'s amplitude falls by the same fraction each cycle: from 10.0 cm to 8.0 cm in one cycle. Calculate its amplitude after 5 cycles.', 10 * 0.8 ** 5, 'cm', 'Fraction per cycle = 8.0 ÷ 10.0 = 0.80. After 5 cycles A = 10.0 × 0.80⁵ = 3.28 cm', ['C1: constant ratio', 'C1: A = A₀ × 0.80ⁿ'], aq='A')
N('M', 3, 'A damped oscillator\'s energy falls from 2.0 J to 0.50 J in 8.0 s. Calculate the ratio of final to initial amplitude.', sqrt(0.5 / 2.0), None, 'A ∝ √E: ratio = √(0.50 ÷ 2.0) = 0.50', ['C1: A ∝ √E', 'C1: substitution'], sig=2, aq='ratio')
M('M', 3, 'A pendulum swings in air and then in water. Which statement is correct?', 'In water the damping is heavier, so the amplitude decays faster and the period is slightly longer', ['In water the amplitude decays more slowly', 'The damping is the same in both', 'In water the period becomes much shorter'], 'Water exerts much larger drag forces, so the energy is lost faster; heavy damping also lengthens the period slightly.', ['C1: greater drag', 'C1: faster decay'])
N('M', 4, 'The amplitude of a damped oscillation decays exponentially: A = A₀e^(−t/τ) with τ = 12 s. Starting with A₀ = 5.0 cm, calculate the amplitude after 20 s.', 5.0 * exp(-20 / 12), 'cm', f'A = 5.0 × e^(−20/12) = 5.0 × e^(−1.667) = {sf(5 * exp(-20 / 12))} cm', ['C1: exponential formula', 'C1: substitution', 'C1: evaluation'], aq='A')
N('M', 3, 'A damped oscillator has amplitude 6.0 cm. 30 s later its amplitude is 3.0 cm. Assuming exponential decay, calculate its amplitude after a further 60 s.', 6.0 / 8, 'cm', 'Halving time = 30 s. A further 60 s is two more halvings: 3.0 ÷ 4 = 0.75 cm', ['C1: constant halving time', 'C1: two further halvings'], sig=2, aq='A')
M('M', 3, 'A bathroom scale needle is critically damped. Why is this better than light damping?', 'The needle settles on the reading quickly without oscillating about it', ['The needle swings past the reading several times', 'The scale reads a larger mass', 'The needle never moves'], 'With light damping the needle would oscillate before settling; critical damping gives the fastest reading.', ['C1: no oscillation', 'C1: quickest settling'])
N('M', 4, 'A lightly damped pendulum loses 5.0 % of its energy each cycle. Calculate the fraction of the original energy left after 20 cycles, and the fraction of the original amplitude. Give the amplitude fraction.', sqrt(0.95 ** 20), None, f'Energy fraction = 0.95²⁰ = {sf(0.95 ** 20)}. Amplitude fraction = √{sf(0.95 ** 20, 4)} = {sf(sqrt(0.95 ** 20))}', ['C1: 0.95ⁿ', 'C1: n = 20', 'C1: A ∝ √E'], aq='fraction')
M('M', 3, 'A car with worn shock absorbers goes over a bump. What happens?', 'It bounces several times before settling, because it is now lightly damped', ['It settles faster', 'It does not move at all', 'It is critically damped'], 'Worn dampers remove less energy each cycle, so the oscillation persists (light damping).', ['C1: less energy removed', 'C1: light damping, oscillates'])
N('M', 3, 'A swing\'s amplitude decreases from 1.2 m to 0.90 m in 10 swings. Calculate the percentage of energy lost in those 10 swings.', (1 - (0.90 / 1.2) ** 2) * 100, '%', 'Energy remaining = (0.90 ÷ 1.2)² = 0.5625, so the percentage lost = (1 − 0.5625) × 100 = 43.75 %', ['C1: E ∝ A²', 'C1: percentage lost'], aq='loss')
N('M', 4, 'A mass–spring system has total energy 0.20 J. Damping removes 0.020 J each cycle at first. The amplitude starts at 4.0 cm. Calculate the amplitude after the first cycle.', 4.0 * sqrt(0.18 / 0.20), 'cm', 'E after one cycle = 0.20 − 0.020 = 0.18 J. A ∝ √E: A = 4.0 × √(0.18 ÷ 0.20) = 3.79 cm', ['C1: new energy', 'C1: A ∝ √E', 'C1: substitution'], aq='A')
M('M', 3, 'Which change would increase the damping of a mass oscillating on a spring?', 'Attaching a large card to the mass to increase air resistance', ['Using a stiffer spring', 'Increasing the amplitude', 'Removing air from around it'], 'More air resistance means more energy is removed per cycle.', ['C1: larger drag force', 'C1: more energy lost per cycle'])
N('M', 3, 'A damped oscillation has period 0.50 s. Its amplitude falls to 1/e of its starting value in 4.0 s. How many oscillations does it make in this time?', 4.0 / 0.50, None, 'N = 4.0 ÷ 0.50 = 8.0 oscillations', ['C1: N = t/T', 'B1: light damping, period unchanged'], sig=2, aq='N')
M('M', 4, 'Two identical pendulums, one with a light bob and one with a heavy bob of the same size, are released together. Which statement is correct?', 'The heavy bob\'s amplitude decreases more slowly because it has more energy for the same air resistance', ['The light bob\'s amplitude decreases more slowly', 'Both decay at the same rate', 'The heavy bob has a longer period'],
  'The drag force depends on size and speed, not mass, so the same energy is lost per cycle; the heavier bob has more energy, so the fractional loss is smaller.', ['C1: same drag', 'C1: more stored energy', 'C1: slower fractional decay'])
N('M', 3, 'The amplitude of a lightly damped oscillator falls from 8.0 mm to 2.0 mm in 12 s. Calculate the time for the amplitude to fall from 8.0 mm to 4.0 mm.', 6.0, 's', 'Exponential decay: 8.0 → 2.0 mm is two halvings in 12 s, so one halving takes 12 ÷ 2 = 6.0 s', ['C1: two halvings', 'C1: constant halving time'], sig=2, aq='t')
N('M', 4, 'After a sound pulse, a loudspeaker cone\'s displacement falls from 0.40 mm to 0.050 mm in 3.0 ms without oscillating, decaying exponentially as A = A₀e^(−t/τ). Calculate the time constant τ.', 3.0e-3 / log(8), 's', f'0.050 ÷ 0.40 = 0.125 = e^(−t/τ), so τ = t/ln 8 = 3.0 × 10⁻³ ÷ ln 8 = {sf(3e-3 / log(8))} s', ['C1: ratio 1/8', 'C1: natural logs', 'C1: τ'], aq='τ')
M('M', 3, 'A student plots ln(amplitude) against time for a lightly damped oscillator. What shape does she expect?', 'A straight line with negative gradient', ['A straight line with positive gradient', 'A parabola', 'An exponential curve'], 'A = A₀e^(−t/τ) gives ln A = ln A₀ − t/τ: linear with gradient −1/τ.', ['C1: ln A = ln A₀ − t/τ', 'C1: negative gradient'])
N('M', 3, 'A lightly damped oscillator\'s amplitude ratio between successive peaks is 0.92. Calculate the fraction of energy lost per cycle.', 1 - 0.92 ** 2, None, 'Energy ratio = 0.92² = 0.8464, so the fraction lost = 1 − 0.8464 = 0.1536', ['C1: energy ratio = (amplitude ratio)²', 'C1: 1 − ratio'], aq='fraction')
# hard
N('H', 6, 'A student records the peak displacements of a damped oscillator at successive cycles: 10.0, 8.5, 7.2, 6.1, 5.2 cm. (a) Show that the decay is exponential. (b) Calculate the fraction of energy lost per cycle. (c) Predict the peak displacement after 10 cycles. Give only the answer to (c).', 10.0 * 0.85 ** 10, 'cm',
  f'(a) Successive ratios: 8.5 ÷ 10.0 = 0.85, 7.2 ÷ 8.5 = 0.85, 6.1 ÷ 7.2 = 0.85, 5.2 ÷ 6.1 = 0.85: constant, so exponential. (b) Energy lost = 1 − 0.85² = {sf(1 - 0.85 ** 2)} per cycle. (c) A = 10.0 × 0.85¹⁰ = {sf(10 * 0.85 ** 10)} cm',
  ['M1: successive ratios', 'A1: constant ratio', 'C1: E ∝ A²', 'A1: fraction lost', 'C1: A₀rⁿ', 'A1: A'], aq='A')
N('H', 5, 'A pendulum (period 2.0 s) is released with amplitude 15 cm. After 5.0 minutes its amplitude is 3.0 cm. Assume exponential decay. (a) Calculate the number of oscillations in 5.0 min. (b) Calculate the fraction of amplitude kept per oscillation. (c) Calculate the time for the amplitude to halve. Give only the answer to (c).', 300 * log(2) / log(5), 's',
  f'(a) 300 ÷ 2.0 = 150 oscillations. (b) r¹⁵⁰ = 3.0 ÷ 15 = 0.20, so r = 0.20^(1/150) = {sf(0.2 ** (1 / 150), 5)}. (c) A halves when t = 300 × ln 2 ÷ ln 5 = {sf(300 * log(2) / log(5))} s',
  ['A1: 150 oscillations', 'C1: rⁿ = 0.20', 'A1: r', 'M1: logs', 'A1: half time'], aq='t')
N('H', 6, 'A car body (mass 1200 kg) on its suspension (k = 4.8 × 10⁴ N m⁻¹) is pushed down 5.0 cm and released. With the dampers disconnected it oscillates; with them connected it is critically damped. (a) Calculate the natural frequency. (b) Calculate the energy stored at release. (c) Describe and compare the motion in the two cases, and state where the energy goes. Give only the answer to (b).', 0.5 * 4.8e4 * 0.05 ** 2, 'J',
  f'(a) f = (1/2π)√(k/m) = (1 ÷ 2π) × √(4.8 × 10⁴ ÷ 1200) = {sf(1 / (2 * pi) * sqrt(40))} Hz. (b) E = ½kx² = 0.5 × 4.8 × 10⁴ × 0.050² = 60 J. (c) Without dampers: many oscillations at about 1 Hz, slowly decaying. Critically damped: returns smoothly to equilibrium in about one quarter-period with no overshoot. The 60 J becomes thermal energy in the damper oil (and tyres).',
  ['C1: f = (1/2π)√(k/m)', 'A1: f', 'C1: E = ½kx²', 'A1: E', 'B1: light damping description', 'B1: critical damping and thermal energy'], sig=2, aq='E')
N('H', 5, 'The energy of a lightly damped oscillator falls to half every 15 s. (a) Calculate the time for the amplitude to fall to half. (b) Calculate the percentage of the amplitude left after 1.0 minute. (c) Explain why the amplitude halving time is longer than the energy halving time. Give only the answer to (a).', 30.0, 's',
  '(a) E ∝ A², so the amplitude halves when the energy has fallen to a quarter: two energy halvings, 2 × 15 = 30 s. (b) 60 s = 2 amplitude halvings: 25 %. (c) Halving A means quartering E, which takes longer than halving E.',
  ['B1: E ∝ A²', 'M1: amplitude halves when E quarters', 'A1: 30 s', 'A1: 25 %', 'B1: explanation'], sig=2, aq='t')
N('H', 6, 'A mass on a spring oscillates in air with period 0.80 s; the amplitude falls from 6.0 cm to 5.4 cm in each cycle. The mass is 0.25 kg. (a) Calculate the spring constant. (b) Calculate the energy at amplitude 6.0 cm. (c) Calculate the average power dissipated by damping during the first cycle. Give only the answer to (c).', 0.5 * (4 * pi ** 2 * 0.25 / 0.64) * (0.06 ** 2 - 0.054 ** 2) / 0.80, 'W',
  f'(a) k = 4π²m/T² = 4π² × 0.25 ÷ 0.80² = {sf(4 * pi ** 2 * 0.25 / 0.64)} N m⁻¹. (b) E = ½kA² = 0.5 × {sf(4 * pi ** 2 * 0.25 / 0.64, 4)} × 0.060² = {sf(0.5 * 4 * pi ** 2 * 0.25 / 0.64 * 0.0036)} J. (c) energy lost = ½k(0.060² − 0.054²) = {sf(0.5 * 4 * pi ** 2 * 0.25 / 0.64 * (0.0036 - 0.002916))} J in 0.80 s, power = {sf(0.5 * 4 * pi ** 2 * 0.25 / 0.64 * (0.0036 - 0.002916), 4)} ÷ 0.80 = {sf(0.5 * 4 * pi ** 2 * 0.25 / 0.64 * (0.0036 - 0.002916) / 0.8)} W',
  ['C1: k = 4π²m/T²', 'A1: k', 'A1: E', 'C1: energy lost in one cycle', 'C1: P = E/t', 'A1: P'], aq='P')

# ═════════════════════════ 18.10 Damped and forced oscillations, resonance (need 16/18/8) ═════════════════════════
lesson('18.10')
M('E', 1, 'A system with natural frequency f₀ is driven at a range of frequencies. What is resonance?', 'A large increase in amplitude when the driving frequency equals the natural frequency', ['The decrease in amplitude caused by damping', 'Oscillation at the natural frequency after the driver stops', 'The energy loss of a driven oscillator'], 'At resonance the driver transfers energy most efficiently, giving maximum amplitude.')
M('E', 1, 'Which is an example of useful resonance?', 'A microwave oven heating water molecules', ['A bridge swaying in the wind', 'A washing machine shaking at one spin speed', 'A car rattling at a certain engine speed'], 'Microwaves at about 2.45 GHz make water molecules absorb energy strongly.')
M('E', 1, 'What is the effect of increasing damping on the resonance peak of a driven oscillator?', 'The peak becomes lower and broader', ['The peak becomes higher and sharper', 'The peak moves to a much higher frequency', 'There is no effect'], 'More damping removes energy faster, reducing the maximum amplitude and spreading the response over more frequencies.')
M('E', 1, 'A singer shatters a wine glass with a note. Which explains this?', 'The note\'s frequency matches the glass\'s natural frequency, so the glass resonates with a large amplitude', ['The sound is very loud at all frequencies', 'The glass is heated by the sound', 'The singer\'s breath pushes the glass'], 'Resonance builds up a large vibration amplitude until the glass breaks.')
N('E', 2, 'A mass–spring system with m = 0.20 kg and k = 80 N m⁻¹ is driven by a variable-frequency vibrator. At what frequency does resonance occur?', 1 / Tspring(0.20, 80), 'Hz', f'f₀ = (1/2π)√(k/m) = (1 ÷ 2π) × √(80 ÷ 0.20) = {sf(1 / Tspring(0.2, 80))} Hz', ['C1: f₀ = (1/2π)√(k/m)'], aq='f₀')
N('E', 2, 'A simple pendulum of length 0.62 m is driven by a series of small pushes. At what driving frequency is the response greatest?' + take('g'), 1 / Tpend(0.62), 'Hz', f'f₀ = (1/2π)√(g/L) = (1 ÷ 2π) × √(9.81 ÷ 0.62) = {sf(1 / Tpend(0.62))} Hz', ['C1: f₀ = (1/2π)√(g/L)'], aq='f₀')
M('E', 1, 'In Barton\'s pendulums, several pendulums hang from a string with a heavy driver pendulum. Which pendulum swings with the largest amplitude?', 'The one with the same length as the driver', ['The shortest one', 'The longest one', 'The lightest one'], 'The pendulum with the same length has the same natural frequency as the driver, so it resonates.')
M('E', 1, 'Why are soldiers told to break step when crossing a small bridge?', 'Marching in step could drive the bridge at its natural frequency and cause resonance', ['To reduce the weight on the bridge', 'To avoid slipping', 'To save energy'], 'Regular footsteps act as a periodic driving force; if its frequency matched the bridge\'s, large oscillations could build up.')
M('E', 1, 'In MRI scanning, radio waves are absorbed by hydrogen nuclei. This is an example of…', 'resonance', ['damping', 'diffraction', 'refraction'], 'The radio frequency matches the precession frequency of the protons in the magnetic field, so they absorb energy strongly.')
M('E', 1, 'A driven oscillator has very little damping. How does its amplitude behave as the driving frequency passes through the natural frequency?', 'It rises to a very large, sharp peak at the natural frequency', ['It stays constant', 'It falls to zero at the natural frequency', 'It rises steadily with frequency'], 'With little damping, resonance gives a tall narrow peak.')
N('E', 2, 'A child\'s swing has natural period 2.4 s. How often (in pushes per minute) should it be pushed for maximum amplitude?', 60 / 2.4, None, 'f₀ = 1/2.4 Hz, so pushes per minute = 60 ÷ 2.4 = 25', ['C1: once per period'], aq='pushes')
M('E', 1, 'Which type of oscillation occurs when a system vibrates at the frequency of a periodic external force?', 'Forced oscillation', ['Free oscillation', 'Damped free oscillation', 'Critical oscillation'], 'A forced oscillation follows the driver\'s frequency.')
M('E', 1, 'Why must the natural frequency of a building\'s structure be kept away from the frequencies of likely earthquakes?', 'To avoid resonance, which would give dangerously large oscillations', ['To make the building lighter', 'To reduce damping', 'To make it oscillate freely'], 'If the ground shakes at the building\'s natural frequency, the amplitude grows and the structure can fail.')
N('E', 2, 'A washing machine on its springs has a natural frequency of 4.5 Hz. At what drum speed, in rev min⁻¹, will it resonate?', 4.5 * 60, 'rev min⁻¹', 'Resonance when the drum turns at 4.5 rev s⁻¹ = 4.5 × 60 = 270 rev min⁻¹', ['C1: × 60'], aq='speed')
M('E', 1, 'Which statement about forced oscillations is correct?', 'The amplitude depends on how close the driving frequency is to the natural frequency', ['The system always oscillates at its natural frequency', 'Damping has no effect on the amplitude', 'The amplitude is largest at very high driving frequency'], 'The response peaks at resonance and is smaller further from it.')
M('E', 2, 'A radio is tuned to a station. Which statement best describes what happens in the tuning circuit?', 'The circuit\'s natural frequency is adjusted to match the station\'s frequency, so it resonates with that signal', ['The circuit absorbs every frequency equally', 'The circuit is critically damped at all frequencies', 'The aerial changes its length'], 'Tuning changes the circuit\'s natural frequency; at resonance it responds strongly to the chosen station only.', ['C1: resonance at chosen frequency'])
# medium
M('M', 3, 'A driven oscillator is heavily damped. Which change to its resonance curve is NOT caused by the damping?', 'The natural frequency becomes much higher', ['The peak amplitude is smaller', 'The peak is broader', 'The peak shifts slightly to a lower frequency'], 'Damping lowers and broadens the peak and shifts it slightly lower; it does not raise the natural frequency.', ['C1: lower, broader peak', 'C1: slight shift to lower frequency'])
N('M', 3, 'A wobbly table has a natural frequency of 6.0 Hz. A washing machine on it spins at 0, then speeds up to 1200 rev min⁻¹. Calculate the drum speed, in rev min⁻¹, at which the table rattles most.', 360, 'rev min⁻¹', 'The drum must turn at 6.0 rev s⁻¹, which is 6.0 × 60 = 360 rev min⁻¹: the table resonates as the drum passes this speed', ['C1: resonance when f_drive = f₀', 'C1: Hz to rev min⁻¹'], sig=2, aq='speed')
M('M', 4, 'At resonance, what is the phase relationship between the driving force and the displacement of a lightly damped oscillator?', 'The displacement lags the driving force by π/2', ['They are in phase', 'They are in antiphase', 'The displacement leads by π/2'], 'At resonance the force is in phase with the velocity, so the displacement lags the force by a quarter cycle — this gives maximum power transfer.', ['C1: force in phase with velocity', 'C1: displacement lags by π/2', 'C1: maximum power transfer'])
N('M', 3, 'A 0.50 kg mass on a spring resonates when driven at 2.8 Hz. Calculate the spring constant.', 4 * pi ** 2 * 0.50 * 2.8 ** 2, 'N m⁻¹', f'k = 4π²mf₀² = 4π² × 0.50 × 2.8² = {sf(4 * pi ** 2 * 0.5 * 7.84)} N m⁻¹', ['C1: f₀ = (1/2π)√(k/m)', 'C1: rearranged'], aq='k')
N('M', 4, 'A car\'s steering wheel vibrates strongly at 25 m s⁻¹ because an unbalanced wheel (radius 0.32 m) drives the steering at its natural frequency. Calculate that natural frequency.', 25 / (2 * pi * 0.32), 'Hz', f'The wheel turns once per circumference: f = v/(2πr) = 25 ÷ (2π × 0.32) = {sf(25 / (2 * pi * 0.32))} Hz', ['B1: driving frequency = wheel rotation rate', 'C1: f = v/2πr', 'C1: substitution'], aq='f₀')
M('M', 3, 'A lightly damped and a heavily damped oscillator with the same natural frequency are driven at the same frequencies. Far below resonance, how do their amplitudes compare?', 'They are almost the same', ['The lightly damped one is much larger', 'The heavily damped one is much larger', 'Both are zero'], 'Far from resonance the amplitude is set mainly by the stiffness (or mass), not the damping. The difference is large only near resonance.', ['C1: damping matters mainly near resonance', 'C1: similar amplitudes'])
N('M', 3, 'A pendulum of length 0.40 m is suspended from a beam that vibrates horizontally. Calculate the period of the beam vibration that would cause resonance.' + take('g'), Tpend(0.40), 's', f'Resonance when T_drive = T₀ = 2π√(L/g) = 2π × √(0.40 ÷ 9.81) = {sf(Tpend(0.4))} s', ['C1: T₀ = 2π√(L/g)', 'C1: drive period = T₀'], aq='T')
M('M', 3, 'Engineers find that a footbridge sways at 1.0 Hz when crowds walk on it. Which fix would most directly stop the resonance?', 'Fit dampers that absorb energy from the sway', ['Paint the bridge', 'Make the crowd walk faster', 'Remove the handrails'], 'Dampers reduce the amplitude at resonance by removing energy each cycle (the Millennium Bridge was fixed this way).', ['C1: damping reduces resonance amplitude', 'C1: identifies dampers'])
N('M', 4, 'A 2.0 kg mass on a spring of constant 200 N m⁻¹ is driven at a variable frequency. The driver is set to 1.0 Hz and then slowly increased. Calculate the frequency at which the amplitude peaks, and the factor by which this exceeds the starting frequency. Give the peak frequency.', 1 / Tspring(2.0, 200), 'Hz', f'f₀ = (1 ÷ 2π) × √(200 ÷ 2.0) = {sf(1 / Tspring(2, 200))} Hz, which is {sf(1 / Tspring(2, 200))} ÷ 1.0 = {sf(1 / Tspring(2, 200))} times the start', ['C1: f₀ formula', 'C1: substitution', 'B1: ratio'], aq='f₀')
M('M', 3, 'Why does a lightly damped forced oscillator take a long time to settle to a steady amplitude after the driver is switched on?', 'Energy builds up gradually over many cycles until the energy lost per cycle equals the energy supplied', ['The driver takes time to warm up', 'The natural frequency changes slowly', 'Damping is large at first'], 'Steady state is reached when input power equals loss; with little damping the loss is small, so amplitude (and energy) builds up over many cycles.', ['C1: energy builds up', 'C1: input = loss at steady state'])
N('M', 3, 'A wine glass has a natural frequency of 880 Hz. A loudspeaker plays a note one octave lower. By what factor is the driving frequency below the natural frequency?', 2.0, None, 'An octave lower is half the frequency: 440 Hz, which is 880 ÷ 440 = 2.0 times lower, so the glass does not resonate', ['C1: octave = factor 2', 'C1: ratio'], sig=2, aq='factor')
M('M', 4, 'A student drives a mass–spring system and plots amplitude against frequency for two damping settings. Curve X has a peak of 8 cm at 2.0 Hz; curve Y has a peak of 3 cm at 1.95 Hz. Which conclusion is correct?', 'Y is more heavily damped than X', ['X is more heavily damped than Y', 'Y has a higher natural frequency', 'Both have the same damping'], 'Heavier damping gives a lower peak at a slightly lower frequency: Y.', ['C1: lower peak', 'C1: slightly lower frequency', 'C1: more damping'])
N('M', 3, 'In a car, a loose panel rattles when the engine runs at 2400 rev min⁻¹. The engine produces two vibration pulses per revolution. Calculate the natural frequency of the panel.', 2 * 2400 / 60, 'Hz', 'Revolutions per second = 2400 ÷ 60 = 40. Driving frequency = 2 × 40 = 80 Hz = natural frequency of the panel', ['C1: rev s⁻¹', 'C1: × 2 pulses'], sig=2, aq='f₀')
M('M', 3, 'Why are car engines mounted on rubber blocks?', 'The rubber damps vibrations so they are not passed strongly to the car body, and reduces the size of any resonance', ['To make the engine resonate', 'To increase the engine\'s power', 'To keep the engine warm'], 'Rubber absorbs energy (damping) and isolates the body from engine vibrations.', ['C1: damping', 'C1: reduces transmitted vibration'])
N('M', 4, 'A pendulum clock is placed on a shelf that vibrates at 0.70 Hz. Calculate the pendulum length that would resonate with the shelf, and say whether the usual 0.99 m pendulum would. Give the length.' + take('g'), 9.81 / (2 * pi * 0.70) ** 2, 'm', f'L = g/(2πf)² = 9.81 ÷ (2π × 0.70)² = {sf(9.81 / (1.4 * pi) ** 2)} m. A 0.99 m pendulum has f₀ = 0.50 Hz, so it would not resonate.', ['C1: f₀ = (1/2π)√(g/L)', 'C1: rearranged for L', 'B1: comparison'], aq='L')
M('M', 3, 'A tall chimney is fitted with spiral strakes on its outside. Why?', 'They break up the regular vortices shed by the wind, which could otherwise drive the chimney at its natural frequency', ['They make the chimney heavier', 'They increase the wind speed', 'They make the chimney stiffer'], 'Wind shedding regular vortices produces a periodic force; disrupting it prevents resonance.', ['C1: periodic driving from vortices', 'C1: prevents resonance'])
# hard
N('H', 6, 'A mass–spring system (m = 0.40 kg, k = 64 N m⁻¹) is driven by a vibrator. Readings of amplitude A against frequency f: 1.0 Hz 0.8 cm; 1.5 Hz 2.0 cm; 2.0 Hz 7.5 cm; 2.5 Hz 2.2 cm; 3.0 Hz 0.9 cm. (a) Calculate the natural frequency. (b) State which reading is closest to resonance and comment. (c) Predict how the curve changes if a card is attached to the mass. Give only the answer to (a).', 1 / Tspring(0.40, 64), 'Hz',
  f'(a) f₀ = (1/2π)√(k/m) = (1 ÷ 2π) × √(64 ÷ 0.40) = {sf(1 / Tspring(0.4, 64))} Hz. (b) 2.0 Hz gives the largest amplitude (7.5 cm), as expected since f₀ ≈ 2.0 Hz. (c) More air resistance: the peak is lower and broader, and shifts slightly to a lower frequency.',
  ['C1: f₀ formula', 'C1: substitution', 'A1: f₀', 'B1: peak at 2.0 Hz', 'B1: lower peak', 'B1: broader, slightly lower frequency'], aq='f₀')
N('H', 5, 'A washing machine (drum assembly 50 kg) on springs of total stiffness 3.2 × 10⁴ N m⁻¹ spins up to 1400 rev min⁻¹. (a) Calculate its natural frequency. (b) Calculate the spin speed, in rev min⁻¹, at which it resonates. (c) Explain why it shakes briefly while spinning up but runs smoothly at full speed. Give only the answer to (b).', 60 / Tspring(50, 3.2e4), 'rev min⁻¹',
  f'(a) f₀ = (1 ÷ 2π) × √(3.2 × 10⁴ ÷ 50) = {sf(1 / Tspring(50, 3.2e4))} Hz. (b) {sf(1 / Tspring(50, 3.2e4), 4)} × 60 = {sf(60 / Tspring(50, 3.2e4))} rev min⁻¹. (c) The drum passes through the resonant speed on the way up, so the shaking is brief. At 1400 rev min⁻¹ the driving frequency is far above f₀ and the response is small.',
  ['C1: f₀ formula', 'A1: f₀', 'A1: resonant speed', 'B1: passes through resonance', 'B1: far from f₀ at full speed'], aq='speed')
N('H', 6, 'An engineer models a footbridge as a mass of 1.2 × 10⁵ kg on a spring, with sideways natural frequency 0.90 Hz. (a) Calculate the effective sideways stiffness. (b) Pedestrians walking at 1.8 steps per second push sideways at half the step rate. Explain why the bridge resonates. (c) Dampers are fitted that remove 30 % of the oscillation energy each cycle. Calculate the fraction of amplitude remaining after 5 cycles once the crowd leaves. Give only the answer to (c).', sqrt(0.70 ** 5), None,
  f'(a) k = 4π²mf₀² = 4π² × 1.2 × 10⁵ × 0.90² = {sf(4 * pi ** 2 * 1.2e5 * 0.81)} N m⁻¹. (b) Sideways driving frequency = 1.8 ÷ 2 = 0.90 Hz = f₀. (c) Energy left = 0.70⁵ = {sf(0.7 ** 5)}, amplitude fraction = √{sf(0.7 ** 5, 4)} = {sf(sqrt(0.7 ** 5))}',
  ['C1: k = 4π²mf²', 'A1: k', 'B1: 0.90 Hz = f₀', 'C1: 0.70ⁿ', 'C1: A ∝ √E', 'A1: fraction'], aq='fraction')
N('H', 5, 'A pendulum of length 1.50 m hangs from a horizontal rod. The rod is moved back and forth with a small amplitude, starting slowly and gradually increasing the frequency. (a) Calculate the frequency at which the pendulum swings most. (b) Describe the phase of the pendulum relative to the rod well below and well above this frequency. Give only the answer to (a).' + take('g'), 1 / Tpend(1.50), 'Hz',
  f'(a) f₀ = (1/2π)√(g/L) = (1 ÷ 2π) × √(9.81 ÷ 1.50) = {sf(1 / Tpend(1.5))} Hz. (b) Well below f₀ the bob moves in phase with the rod (it simply follows it). At f₀ it lags by π/2 with a large amplitude. Well above f₀ it moves in antiphase with a small amplitude.',
  ['C1: f₀ formula', 'A1: f₀', 'B1: in phase below', 'B1: π/2 at resonance', 'B1: antiphase above'], aq='f₀')
N('H', 6, 'A 0.25 kg mass on a spring (k = 25 N m⁻¹) is driven at resonance. Damping removes energy at a rate P = bv², with b = 0.20 kg s⁻¹, and the steady amplitude is 4.0 cm. (a) Calculate the natural angular frequency. (b) Calculate the maximum speed. (c) Calculate the average power the driver supplies (the average of v² is half its maximum). Give only the answer to (c).', 0.20 * (10 * 0.04) ** 2 / 2, 'W',
  f'(a) ω₀ = √(k/m) = √(25 ÷ 0.25) = 10 rad s⁻¹. (b) v_max = ω₀A = 10 × 0.040 = 0.40 m s⁻¹. (c) average power = b × ½v_max² = 0.20 × 0.5 × 0.40² = {sf(0.2 * 0.5 * 0.16)} W (at steady state the driver supplies exactly what damping removes).',
  ['C1: ω₀ = √(k/m)', 'A1: ω₀', 'A1: v_max', 'C1: P = b × mean v²', 'B1: input = loss at steady state', 'A1: P'], aq='P')
N('H', 5, 'An earthquake shakes the ground at 1.5 Hz. Three buildings have natural frequencies: P 0.4 Hz, Q 1.5 Hz, R 4.0 Hz. (a) State which building is most at risk and why. (b) Building Q is modelled as a 2.0 × 10⁶ kg mass on a spring. Calculate its effective stiffness. (c) Suggest two ways to protect Q. Give only the answer to (b).', 4 * pi ** 2 * 2.0e6 * 1.5 ** 2, 'N m⁻¹',
  f'(a) Q: its natural frequency equals the driving frequency, so it resonates with a large amplitude. (b) k = 4π²mf² = 4π² × 2.0 × 10⁶ × 1.5² = {sf(4 * pi ** 2 * 2e6 * 2.25)} N m⁻¹. (c) Add damping (dampers or a tuned mass damper) and/or change the stiffness or mass so f₀ moves away from 1.5 Hz (or use base isolation).',
  ['B1: Q', 'B1: resonance reason', 'C1: k = 4π²mf²', 'A1: k', 'B1: two valid methods'], aq='k')

# ── extras to reach 50 ──
lesson('18.6')
N('M', 3, 'A hovering bee\'s wings beat with angular frequency 1.4 × 10³ rad s⁻¹. Calculate the number of wing beats in 2.0 s.', 1.4e3 * 2.0 / (2 * pi), None, f'f = ω/2π = 1.4 × 10³ ÷ 2π = {sf(1.4e3 / (2 * pi))} Hz. N = ft = {sf(1.4e3 / (2 * pi), 4)} × 2.0 = {sf(2.8e3 / (2 * pi))}', ['C1: f = ω/2π', 'C1: N = ft', 'C1: substitution'], aq='N', tol=0.02)

lesson('18.7')
N('H', 5, 'A trolley between springs oscillates with x = 0.060 sin(3.0t) m. (a) State x₀ and ω. (b) Calculate the time from t = 0 at which the trolley first has a speed of 0.090 m s⁻¹. (c) Calculate its displacement at that moment. Give only the answer to (b).', (1 / 3.0) * acos(0.090 / 0.18), 's',
  f'(a) x₀ = 0.060 m, ω = 3.0 rad s⁻¹. (b) v = ωx₀ cos ωt = 0.18 cos 3.0t = 0.090, so cos 3.0t = 0.50, 3.0t = cos⁻¹ 0.50 = 60°, which is π/3 rad, and t = (π/3) ÷ 3.0 = {sf(pi / 9)} s. (c) x = 0.060 × sin 60° = {sf(0.06 * sin(pi / 3))} m',
  ['B1: x₀ and ω', 'C1: v = ωx₀ cos ωt', 'C1: cos 3t = 0.5', 'A1: t', 'B1: x'], aq='t')
N('H', 6, 'A mass oscillating with s.h.m. passes x = 2.0 cm with speed 0.30 m s⁻¹ and x = 4.0 cm with speed 0.20 m s⁻¹. (a) Use v² = ω²(x₀² − x²) to find ω. (b) Find the amplitude. (c) Find the maximum acceleration. Give only the answer to (c).', 0.05 / 0.0012 * sqrt(0.0004 + 0.09 / (0.05 / 0.0012)), 'm s⁻²',
  f'(a) 0.30² − 0.20² = ω²(0.040² − 0.020²): 0.050 = ω² × 0.0012, ω² = {sf(0.05 / 0.0012)} s⁻², ω = {sf(sqrt(0.05 / 0.0012))} rad s⁻¹. (b) x₀² = 0.020² + 0.30² ÷ ω² = 0.0004 + 0.09 ÷ {sf(0.05 / 0.0012, 4)} = {sf(0.0004 + 0.09 / (0.05 / 0.0012))} m², x₀ = {sf(sqrt(0.0004 + 0.09 / (0.05 / 0.0012)))} m. (c) a_max = ω²x₀ = {sf(0.05 / 0.0012, 4)} × {sf(sqrt(0.0004 + 0.09 / (0.05 / 0.0012)), 4)} = {sf(0.05 / 0.0012 * sqrt(0.0004 + 0.09 / (0.05 / 0.0012)))} m s⁻²',
  ['M1: subtract the two equations', 'A1: ω', 'C1: x₀² from one equation', 'A1: x₀', 'C1: a_max = ω²x₀', 'A1: a_max'], aq='a_max')

lesson('18.8')
N('H', 5, 'A 0.15 kg mass on a spring (k = 60 N m⁻¹) oscillates with amplitude 5.0 cm. (a) Calculate the total energy. (b) Calculate the displacement at which the kinetic energy is 0.050 J. (c) Calculate the speed there. Give only the answer to (b).', sqrt((0.5 * 60 * 0.05 ** 2 - 0.050) * 2 / 60), 'm',
  f'(a) E = ½kx₀² = 0.5 × 60 × 0.050² = 0.075 J. (b) Ep = 0.075 − 0.050 = 0.025 J, x = √(2Ep/k) = √(2 × 0.025 ÷ 60) = {sf(sqrt(0.05 / 60))} m. (c) v = √(2Ek/m) = √(2 × 0.050 ÷ 0.15) = {sf(sqrt(0.1 / 0.15))} m s⁻¹',
  ['A1: E', 'C1: Ep = E − Ek', 'C1: x = √(2Ep/k)', 'A1: x', 'B1: v'], aq='x')
N('H', 6, 'A 0.50 kg pendulum bob on a 2.0 m string is pulled aside so that it is 10 cm higher than its lowest point, and released. (a) Calculate its maximum speed. (b) Calculate the total energy. (c) Air resistance removes 2.0 % of the energy each swing. Calculate the height it reaches after 10 swings. Give only the answer to (c).' + take('g'), 0.10 * 0.98 ** 10, 'm',
  f'(a) v = √(2gh) = √(2 × 9.81 × 0.10) = {sf(sqrt(1.962))} m s⁻¹. (b) E = mgh = 0.50 × 9.81 × 0.10 = {sf(0.4905)} J. (c) Energy (and so height) after 10 swings: h = 0.10 × 0.98¹⁰ = {sf(0.1 * 0.98 ** 10)} m',
  ['C1: v = √(2gh)', 'A1: v', 'A1: E', 'M1: × 0.98 per swing', 'B1: h ∝ E', 'A1: h'], aq='h')

lesson('18.9')
N('M', 3, 'A swing\'s amplitude falls to 70 % of its value every 4 swings. Calculate the amplitude after 12 swings if it started at 1.0 m.', 1.0 * 0.70 ** 3, 'm', 'Three lots of 4 swings: A = 1.0 × 0.70³ = 0.343 m', ['C1: number of 4-swing intervals', 'C1: 0.70ⁿ'], aq='A')
N('H', 5, 'A lightly damped spring–mass system (m = 0.40 kg, k = 40 N m⁻¹) starts with amplitude 8.0 cm. After 20 oscillations the amplitude is 4.0 cm. (a) Calculate the initial energy. (b) Calculate the energy after 20 oscillations. (c) Calculate the mean power dissipated over the 20 oscillations. Give only the answer to (c).', (0.5 * 40 * (0.08 ** 2 - 0.04 ** 2)) / (20 * Tspring(0.40, 40)), 'W',
  f'(a) E = ½kA² = 0.5 × 40 × 0.080² = 0.128 J. (b) E = 0.5 × 40 × 0.040² = 0.032 J. (c) T = 2π√(m/k) = 2π × √(0.40 ÷ 40) = {sf(Tspring(0.4, 40))} s, 20T = {sf(20 * Tspring(0.4, 40))} s, P = (0.128 − 0.032) ÷ {sf(20 * Tspring(0.4, 40), 4)} = {sf(0.096 / (20 * Tspring(0.4, 40)))} W',
  ['A1: E initial', 'A1: E final', 'C1: period', 'C1: P = ΔE/Δt', 'A1: P'], aq='P')
N('H', 6, 'The amplitude A of a damped oscillation is measured: t = 0, 10.0 cm; t = 10 s, 7.4 cm; t = 20 s, 5.5 cm; t = 30 s, 4.1 cm. (a) Show that A decays exponentially. (b) Calculate the time constant τ in A = A₀e^(−t/τ). (c) Predict A at t = 60 s. Give only the answer to (c).', 10.0 * exp(-60 / (10 / log(10 / 7.4))), 'cm',
  f'(a) Ratios over each 10 s: 7.4 ÷ 10.0 = 0.74, 5.5 ÷ 7.4 = 0.74, 4.1 ÷ 5.5 = 0.75: constant, so exponential. (b) e^(−10/τ) = 0.74, so τ = 10 ÷ ln(1 ÷ 0.74) = {sf(10 / log(1 / 0.74))} s. (c) A = 10.0 × e^(−60/{sf(10 / log(10 / 7.4), 4)}) = {sf(10 * exp(-60 / (10 / log(10 / 7.4))))} cm',
  ['M1: constant ratio in equal times', 'A1: exponential', 'C1: ln of ratio', 'A1: τ', 'C1: substitution', 'A1: A'], aq='A')
N('H', 5, 'A car (mass 1000 kg) on its springs (total k = 4.0 × 10⁴ N m⁻¹) is critically damped by its shock absorbers. (a) Calculate the undamped natural period. (b) Explain why a critically damped car is more comfortable than a lightly damped one. (c) Explain why an overdamped car would also be unsatisfactory. Give only the answer to (a).', Tspring(1000, 4.0e4), 's',
  f'(a) T = 2π√(m/k) = 2π × √(1000 ÷ 4.0 × 10⁴) = {sf(Tspring(1000, 4e4))} s. (b) After a bump it returns to its rest position quickly without bouncing up and down. (c) It would return to equilibrium very slowly, so it might still be compressed when the next bump arrives, giving a harsh ride.',
  ['C1: T = 2π√(m/k)', 'A1: T', 'B1: no oscillation', 'B1: quick return', 'B1: overdamped slow return'], aq='T')
N('H', 6, 'A pendulum clock\'s pendulum (energy 0.020 J at full amplitude) loses 0.30 % of its energy each swing to friction. A weight falls slowly to replace this energy. (a) Calculate the energy lost per swing. (b) The period is 2.0 s. Calculate the power the weight must supply. (c) The weight (5.0 kg) falls 1.0 m. Estimate how many days the clock runs per winding. Give only the answer to (c).' + take('g'), (5.0 * 9.81 * 1.0) / (0.003 * 0.020 / 2.0) / 86400, 'days',
  f'(a) ΔE = 0.0030 × 0.020 = 6.0 × 10⁻⁵ J per swing. (b) P = 6.0 × 10⁻⁵ ÷ 2.0 = 3.0 × 10⁻⁵ W. (c) Energy available = mgh = 5.0 × 9.81 × 1.0 = 49 J. Time = 49.05 ÷ 3.0 × 10⁻⁵ = {sf(49.05 / 3e-5)} s. In days: {sf(49.05 / 3e-5, 4)} ÷ 86400 = {sf(49.05 / 3e-5 / 86400)}',
  ['A1: ΔE per swing', 'C1: P = ΔE/T', 'A1: P', 'C1: mgh', 'C1: t = E/P', 'A1: days'], aq='days')
N('H', 5, 'A mass oscillates on a spring in air; then the same system is placed in water. In air the amplitude halves every 40 oscillations; in water it halves every 3 oscillations. (a) Calculate the amplitude fraction kept per oscillation in water. (b) Calculate the fraction of energy lost per oscillation in water. (c) Describe the effect of the water on the period. Give only the answer to (b).', 1 - 0.5 ** (2 / 3), None,
  f'(a) r³ = 0.5, r = 0.5^(1/3) = {sf(0.5 ** (1 / 3))}. (b) Energy kept per cycle = r² = {sf(0.5 ** (2 / 3))}, so lost = 1 − {sf(0.5 ** (2 / 3), 4)} = {sf(1 - 0.5 ** (2 / 3))}. (c) Heavier damping lengthens the period slightly.',
  ['C1: r³ = 0.5', 'A1: r', 'C1: energy ∝ A²', 'A1: fraction lost', 'B1: period slightly longer'], aq='fraction')

lesson('18.10')
M('M', 3, 'Which statement about the frequency at which a lightly damped oscillator responds most strongly is correct?', 'It is very close to (just below) the natural frequency', ['It is twice the natural frequency', 'It is half the natural frequency', 'It is independent of the natural frequency'], 'With light damping, the amplitude peaks at a driving frequency just below f₀.', ['C1: peak near f₀', 'C1: slightly below for damped system'])
N('M', 3, 'A loudspeaker drives an air-filled tube whose air column resonates at 280 Hz. Calculate the driving period at resonance in milliseconds.', 1000 / 280, 'ms', f'T = 1/f = 1 ÷ 280 = {sf(1 / 280)} s. In ms: {sf(1 / 280, 4)} × 1000 = {sf(1000 / 280)} ms', ['C1: resonance at f₀', 'C1: T = 1/f'], aq='T')
N('H', 5, 'A 0.20 kg mass on a spring (k = 20 N m⁻¹) is driven by a motor whose frequency rises from 0.20 Hz to 3.0 Hz. (a) Calculate the natural frequency. (b) Explain, in terms of energy transfer, why the amplitude is greatest near this frequency. (c) The mass is replaced by one of 0.80 kg. State the new resonant frequency. Give only the answer to (c).', 1 / Tspring(0.80, 20), 'Hz',
  f'(a) f₀ = (1 ÷ 2π) × √(20 ÷ 0.20) = {sf(1 / Tspring(0.2, 20))} Hz. (b) At f₀ the driving force is in phase with the velocity, so it does positive work on the mass throughout each cycle: maximum energy transfer. (c) Four times the mass halves f₀: f₀ = {sf(1 / Tspring(0.2, 20), 4)} ÷ 2 = {sf(1 / Tspring(0.8, 20))} Hz',
  ['A1: f₀', 'B1: force in phase with velocity', 'B1: maximum energy transfer', 'C1: f ∝ 1/√m', 'A1: new f₀'], aq='f₀')
N('H', 6, 'A tall building has natural frequency 0.25 Hz and effective mass 4.0 × 10⁷ kg. During a storm, wind gusts arrive every 4.0 s. (a) Explain why the building may sway dangerously. (b) Calculate the effective stiffness. (c) Engineers stiffen the structure so that k increases by 44 %. Calculate the new natural frequency. Give only the answer to (c).', 0.25 * sqrt(1.44), 'Hz',
  f'(a) Gusts every 4.0 s means f = 0.25 Hz, equal to f₀: resonance. (b) k = 4π²mf² = 4π² × 4.0 × 10⁷ × 0.25² = {sf(4 * pi ** 2 * 4e7 * 0.0625)} N m⁻¹. (c) f ∝ √k: f = 0.25 × √1.44 = {sf(0.25 * 1.2)} Hz, now away from the gust frequency.',
  ['B1: 0.25 Hz drive equals f₀', 'C1: k = 4π²mf²', 'A1: k', 'C1: f ∝ √k', 'A1: new f', 'B1: avoids resonance'], aq='f')
